import { PetState } from "@/state/types";
import { paintDog } from "@/pixel/renderer";
import { DogFrame } from "@/pixel/dogModel";
import { companionDay } from "@/utils/date";
import { SKIN_INFO } from "./evolution";

function statusText(pet: PetState): string {
  if (pet.skins.active === "health_guru") return "养生达人 · 满血";
  const n = new Set(pet.health.todayTypes).size;
  if (n >= 3) return "今日满状态 ✦";
  if (n >= 1) return "渐入佳境";
  if (new Date().getHours() >= 15) return "幽怨中…快动一动";
  return "待唤醒";
}

// 生成像素风健康战绩卡片，返回 canvas 元素
export function buildScorecard(pet: PetState): HTMLCanvasElement {
  const W = 360;
  const H = 480;
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const ctx = c.getContext("2d")!;
  ctx.imageSmoothingEnabled = false;

  // 背景 + 硬边框
  ctx.fillStyle = "#FBEFD9";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#4A3527";
  ctx.fillRect(0, 0, W, 8);
  ctx.fillRect(0, H - 8, W, 8);
  ctx.fillRect(0, 0, 8, H);
  ctx.fillRect(W - 8, 0, 8, H);
  // 顶部色带
  ctx.fillStyle = "#7FB069";
  ctx.fillRect(8, 8, W - 16, 52);

  const cx = W / 2;
  ctx.textAlign = "center";
  ctx.fillStyle = "#FBEFD9";
  ctx.font = "bold 26px 'ZCOOL QingKe HuangYou', sans-serif";
  ctx.fillText("健康战绩", cx, 44);

  // 小狗头像
  const avatar = document.createElement("canvas");
  avatar.width = 132;
  avatar.height = 132;
  const frame: DogFrame = {
    eye: "happy", mouth: "smile", legKick: 0, earTilt: 0.4, look: 0,
    tailWag: 0, blush: true, skin: pet.skins.active,
  };
  paintDog(avatar, frame);
  ctx.drawImage(avatar, cx - 66, 74, 132, 132);

  ctx.fillStyle = "#4A3527";
  ctx.font = "bold 22px 'ZCOOL QingKe HuangYou', sans-serif";
  ctx.fillText(pet.profile.name, cx, 232);
  ctx.font = "14px 'ZCOOL QingKe HuangYou', sans-serif";
  ctx.fillStyle = "#8C6B4F";
  ctx.fillText(`陪你的第 ${companionDay(pet.profile.firstOpen)} 天`, cx, 256);

  // 数据行
  const rows: [string, string][] = [
    ["连续打卡", `${pet.health.streakDays} 天`],
    ["总打卡次数", `${pet.health.totalChecks} 次`],
    ["今日状态", statusText(pet)],
    ["当前形态", SKIN_INFO[pet.skins.active].name],
  ];
  let y = 290;
  ctx.textAlign = "left";
  for (const [k, v] of rows) {
    ctx.fillStyle = "#F0DEBE";
    ctx.fillRect(28, y, W - 56, 34);
    ctx.fillStyle = "#4A3527";
    ctx.fillRect(28, y, 6, 34);
    ctx.font = "16px 'ZCOOL QingKe HuangYou', sans-serif";
    ctx.fillText(k, 46, y + 23);
    ctx.textAlign = "right";
    ctx.font = "bold 18px 'ZCOOL QingKe HuangYou', sans-serif";
    ctx.fillText(v, W - 42, y + 23);
    ctx.textAlign = "left";
    y += 42;
  }

  ctx.textAlign = "center";
  ctx.fillStyle = "#C0392B";
  ctx.font = "14px 'ZCOOL QingKe HuangYou', sans-serif";
  ctx.fillText("★ 分享你的健康战绩 ★", cx, H - 24);

  return c;
}
