import { create } from "zustand";
import { PetState, Mood, HealthType, DiaryEntry, Gender } from "./types";
import { loadState, saveState, defaultState, resetState } from "./storage";
import { SkinId } from "@/pixel/palette";
import { pick, pickHealth, Scene } from "@/logic/copy";
import {
  evaluateUnlocks,
  isGrumpyCoach,
  preferredSkin,
  SKIN_INFO,
} from "@/logic/evolution";
import { generateDiary, greetingFromDiary } from "@/logic/diary";
import {
  companionDay,
  isBirthdayToday,
  isLateNight,
  isOffHours,
  todayISO,
} from "@/utils/date";

export type ConfettiKind = "fireworks" | "petals" | "stars";

interface Ephemeral {
  mood: Mood;
  bubble: { text: string; id: number } | null;
  showOnboarding: boolean;
  focus: { endsAt: number; total: number } | null;
  reminder: { type: HealthType; text: string } | null;
  scorecardOpen: boolean;
  diaryOpen: boolean;
  confetti: { kind: ConfettiKind; id: number } | null;
  hidden: boolean;
  speedX: number;
  screenSharing: boolean;
  snoozeUntil: number;
  newSkin: SkinId | null;
  lowPower: boolean; // 低电量/低能耗模式（桌面端由 powerMonitor 提供，预览页可调试）
  chatApp: boolean; // 当前活动窗口疑似办公消息类（微信/钉钉/飞书）——桌面端占位，预览页可调试
}

interface Store extends Ephemeral {
  pet: PetState;
  init: () => void;
  reset: () => void;
  say: (scene: Scene) => void;
  sayText: (text: string) => void;
  setMood: (mood: Mood, ms?: number) => void;
  petHead: () => void;
  petChin: () => void;
  toggleHidden: () => void;
  completeOnboarding: (name: string, gender: Gender, birthday: string) => void;
  startFocus: () => void;
  endFocus: (completed: boolean) => void;
  triggerReminder: (type?: HealthType) => void;
  healthCheck: () => void;
  snooze: () => void;
  dismissReminder: () => void;
  setScorecard: (v: boolean) => void;
  setDiaryOpen: (v: boolean) => void;
  writeDiary: () => void;
  setPosition: (x: number, y: number) => void;
  fireConfetti: (kind: ConfettiKind) => void;
  setSpeed: (x: number) => void;
  setScreenSharing: (v: boolean) => void;
  tickReminder: () => void;
  clearNewSkin: () => void;
  // —— 实时互动反应 ——
  reactBattle: (chat: boolean) => void; // 高频输入进入备战
  reactAlert: () => void; // 低电量转向屏幕外侧警惕
  reactAway: (long: boolean) => void; // 离开键盘（15/45 分钟）
  setLowPower: (v: boolean) => void;
  setChatApp: (v: boolean) => void;
  // —— demo 调试 ——
  demoBirthday: () => void;
  unlockAllSkins: () => void;
  setSkin: (id: SkinId) => void;
}

let moodTimer: ReturnType<typeof setTimeout> | null = null;
let bubbleTimer: ReturnType<typeof setTimeout> | null = null;
let bubbleSeq = 0;
let confettiSeq = 0;

const REMINDER_ORDER: HealthType[] = ["water", "pee", "sit"];
const BASE_INTERVAL_MS = 45 * 60 * 1000;

const REACT_SCENE = {
  battleWork: "battleWork",
  battleChat: "battleChat",
  alert: "alert",
  awayShort: "awayShort",
  awayLong: "awayLong",
} as const;
// 健康提醒按“开机时长”计时：记录上次提醒（或应用启动）的时间基准
let reminderAnchor = Date.now();

export const usePetStore = create<Store>((set, get) => {
  const persist = () => saveState(get().pet);
  const mutate = (fn: (p: PetState) => void) => {
    const pet = structuredClone(get().pet);
    fn(pet);
    set({ pet });
    saveState(pet);
  };

  const setBubble = (text: string, ms = 4200) => {
    if (bubbleTimer) clearTimeout(bubbleTimer);
    bubbleSeq += 1;
    set({ bubble: { text, id: bubbleSeq } });
    bubbleTimer = setTimeout(() => set({ bubble: null }), ms);
  };

  const setMoodFor = (mood: Mood, ms = 2600) => {
    if (moodTimer) clearTimeout(moodTimer);
    set({ mood });
    // idle 常驻不回退；其余情绪（含睡觉）到时自动回到 idle
    if (mood !== "idle") {
      moodTimer = setTimeout(() => set({ mood: "idle" }), ms);
    }
  };

  // 实时互动反应的共用守卫：隐藏/专注/健康提醒/引导/共享屏幕时不打扰
  const canReact = () => {
    const s = get();
    return !(s.hidden || s.focus || s.reminder || s.showOnboarding || s.screenSharing);
  };

  const checkUnlocks = () => {
    const gained = evaluateUnlocks(get().pet);
    if (gained.length === 0) return;
    const skin = gained[gained.length - 1];
    mutate((p) => {
      p.skins.unlocked = Array.from(new Set([...p.skins.unlocked, ...gained]));
      p.skins.active = skin;
    });
    set({ newSkin: skin });
    get().fireConfetti("stars");
    const scene: Scene =
      skin === "night_owl"
        ? "nightOwl"
        : skin === "workaholic"
        ? "workaholic"
        : skin === "health_guru"
        ? "healthGuru"
        : "idle";
    setTimeout(() => setBubble(`解锁新形态·${SKIN_INFO[skin].name}！\n${pick(scene, get().pet.profile.name)}`, 5200), 400);
  };

  return {
    pet: defaultState(),
    mood: "idle",
    bubble: null,
    showOnboarding: false,
    focus: null,
    reminder: null,
    scorecardOpen: false,
    diaryOpen: false,
    confetti: null,
    hidden: false,
    speedX: 1,
    screenSharing: false,
    snoozeUntil: 0,
    newSkin: null,
    lowPower: false,
    chatApp: false,

    init: () => {
      reminderAnchor = Date.now();
      const loaded = loadState();
      const today = todayISO();
      // 天数滚动 & 连续打卡断裂判断
      if (loaded.health.todayDate !== today) {
        loaded.health.todayDate = today;
        loaded.health.todayTypes = [];
        loaded.health.activeMsAccum = 0;
        const last = loaded.health.lastCheckDate;
        const gap = last ? Math.abs(new Date(today).getTime() - new Date(last).getTime()) / 86400000 : 999;
        if (gap > 1.5) loaded.health.streakDays = 0;
      }
      // 深夜打开累计
      if (isLateNight()) loaded.counters.lateNightOpens += 1;
      // 生日计数按日期归零
      if (loaded.counters.birthdayPetsDate !== today) {
        loaded.counters.birthdayPets = 0;
        loaded.counters.birthdayPetsDate = today;
      }
      // 自动跟随已解锁的进化态
      loaded.skins.active = preferredSkin(loaded);
      set({ pet: loaded });
      saveState(loaded);

      if (!loaded.profile.onboarded) {
        set({ showOnboarding: true });
        setTimeout(() => setBubble(pick("onboarding", loaded.profile.name), 6000), 600);
        return;
      }

      // 开场白：生日 > 昨日日记情绪 > 早安
      setTimeout(() => {
        if (isBirthdayToday(loaded.profile.birthday)) {
          get().fireConfetti("fireworks");
          setBubble(pick("birthday", loaded.profile.name), 6000);
          setMoodFor("excited", 4000);
          return;
        }
        const g = greetingFromDiary(loaded.diary, loaded.profile.name);
        const day = companionDay(loaded.profile.firstOpen);
        setBubble(g ?? pick("morning", loaded.profile.name, day), 5200);
      }, 700);

      checkUnlocks();
    },

    reset: () => {
      resetState();
      set({
        pet: defaultState(),
        mood: "idle",
        bubble: null,
        showOnboarding: false,
        focus: null,
        reminder: null,
        scorecardOpen: false,
        diaryOpen: false,
        confetti: null,
        hidden: false,
        snoozeUntil: 0,
        newSkin: null,
      });
      get().init();
    },

    say: (scene) => setBubble(pick(scene, get().pet.profile.name)),
    sayText: (text) => setBubble(text),
    setMood: (mood, ms) => setMoodFor(mood, ms),

    petHead: () => {
      const birthday = isBirthdayToday(get().pet.profile.birthday);
      mutate((p) => {
        p.counters.petHead += 1;
        p.weights.tsundere += 1;
        if (birthday) p.counters.birthdayPets += 1;
      });
      setMoodFor("happy", 2200);
      if (birthday) {
        const n = get().pet.counters.birthdayPets;
        setBubble(`生日快乐我摸到第 ${n} 下啦！${n >= 100 ? "达成一百下，谢谢你！" : "快摸我100下！"}`);
        if (n === 100) get().fireConfetti("fireworks");
      } else {
        get().say("petHead");
      }
    },

    petChin: () => {
      // 傲娇：偶尔躲闪
      const tsundere = get().pet.weights.tsundere >= 8 && get().pet.counters.petHead > get().pet.counters.petChin * 2;
      if (tsundere && Math.random() < 0.1) {
        setMoodFor("sad", 1600);
        get().say("dodge");
        return;
      }
      mutate((p) => {
        p.counters.petChin += 1;
      });
      setMoodFor("happy", 2000);
      get().say("petChin");
    },

    toggleHidden: () => {
      const hidden = !get().hidden;
      set({ hidden });
      if (hidden) {
        mutate((p) => {
          p.counters.bossKey += 1;
          p.weights.alert += 1;
        });
      } else {
        setMoodFor("idle");
      }
    },

    completeOnboarding: (name, gender, birthday) => {
      mutate((p) => {
        p.profile.name = name.trim() || "小狗";
        p.profile.gender = gender;
        p.profile.birthday = birthday;
        p.profile.onboarded = true;
        p.profile.firstOpen = p.profile.firstOpen || todayISO();
      });
      set({ showOnboarding: false });
      setMoodFor("happy", 2600);
      setBubble(`我叫${get().pet.profile.name}啦！这是我陪你的第 ${companionDay(get().pet.profile.firstOpen)} 天～`, 5200);
      if (isBirthdayToday(birthday)) {
        setTimeout(() => {
          get().fireConfetti("fireworks");
          setBubble(pick("birthday", get().pet.profile.name), 6000);
        }, 2600);
      }
    },

    startFocus: () => {
      if (get().focus) return;
      const total = (25 * 60 * 1000) / get().speedX;
      set({ focus: { endsAt: Date.now() + total, total } });
      setMoodFor("focus", 3000);
      get().say("focusStart");
    },

    endFocus: (completed) => {
      set({ focus: null });
      if (completed) {
        mutate((p) => {
          p.counters.focusSessions += 1;
          p.weights.workaholic += 1;
        });
        setMoodFor("happy", 3000);
        get().say("focusEnd");
        checkUnlocks();
      } else {
        setMoodFor("idle");
      }
    },

    triggerReminder: (type) => {
      if (get().reminder || get().hidden || get().focus) return;
      reminderAnchor = Date.now(); // 提醒弹出即重置基准，下一次再等一个间隔
      const last = get().pet.health.lastReminderType;
      const nextIdx = last ? (REMINDER_ORDER.indexOf(last) + 1) % 3 : 0;
      const t = type ?? REMINDER_ORDER[nextIdx];
      const text = pickHealth(t, get().pet.profile.name);
      set({ reminder: { type: t, text } });
      mutate((p) => {
        p.health.lastReminderType = t;
        p.health.activeMsAccum = 0;
      });
      setMoodFor(t === "water" ? "lick" : "excited", 60000);
    },

    healthCheck: () => {
      const r = get().reminder;
      if (!r) return;
      const today = todayISO();
      let reached3 = false;
      mutate((p) => {
        if (!p.health.todayTypes.includes(r.type)) p.health.todayTypes.push(r.type);
        p.health.totalChecks += 1;
        if (p.health.lastCheckDate !== today) {
          const last = p.health.lastCheckDate;
          const gap = last ? Math.abs(new Date(today).getTime() - new Date(last).getTime()) / 86400000 : 999;
          p.health.streakDays = gap <= 1.5 ? p.health.streakDays + 1 : 1;
          p.health.lastCheckDate = today;
        }
        p.health.snoozeCount = 0;
        p.health.mutedUntil = null;
        p.weights.healthGuru += 1;
        reached3 = new Set(p.health.todayTypes).size >= 3;
      });
      set({ reminder: null, snoozeUntil: 0 });
      setMoodFor("thumbsup", 2600);
      if (reached3) {
        get().fireConfetti("petals");
        setBubble(pick("celebrate3", get().pet.profile.name), 5200);
      } else {
        get().say("thumbsup");
      }
      checkUnlocks();
    },

    snooze: () => {
      if (!get().reminder) return;
      let muted = false;
      mutate((p) => {
        p.health.snoozeCount += 1;
        if (p.health.snoozeCount >= 3) {
          p.health.mutedUntil = Date.now() + (2 * 60 * 60 * 1000) / get().speedX;
          muted = true;
        }
      });
      set({
        reminder: null,
        snoozeUntil: Date.now() + (5 * 60 * 1000) / get().speedX,
      });
      setMoodFor("eyeroll", 2200);
      if (muted) {
        get().say("mutedSad");
        setMoodFor("sad", 3000);
      } else {
        get().say("snooze");
      }
    },

    dismissReminder: () => set({ reminder: null }),
    setScorecard: (v) => set({ scorecardOpen: v }),
    setDiaryOpen: (v) => set({ diaryOpen: v }),

    writeDiary: () => {
      const today = todayISO();
      if (get().pet.health.lastDiaryDate === today) {
        setBubble("今天的日记我已经写好啦，去翻翻看？");
        set({ diaryOpen: true });
        return;
      }
      const entry: DiaryEntry = generateDiary(get().pet);
      mutate((p) => {
        p.diary.push(entry);
        p.health.lastDiaryDate = today;
      });
      setBubble(pick("diaryIntro", get().pet.profile.name), 4200);
      setMoodFor("happy", 2600);
      set({ diaryOpen: true });
    },

    setPosition: (x, y) => mutate((p) => (p.position = { x, y })),

    fireConfetti: (kind) => {
      confettiSeq += 1;
      set({ confetti: { kind, id: confettiSeq } });
    },

    setSpeed: (x) => set({ speedX: x }),
    setScreenSharing: (v) => set({ screenSharing: v }),
    clearNewSkin: () => set({ newSkin: null }),

    reactBattle: (chat) => {
      if (!canReact()) return;
      setMoodFor("battle", 2800);
      const name = get().pet.profile.name;
      setBubble(pick(chat ? REACT_SCENE.battleChat : REACT_SCENE.battleWork, name), chat ? 5200 : 4200);
    },

    reactAlert: () => {
      if (!canReact()) return;
      setMoodFor("alert", 3600);
      const name = get().pet.profile.name;
      setBubble(pick(REACT_SCENE.alert, name), 4200);
    },

    reactAway: (long) => {
      if (!canReact()) return;
      // 15 分钟幽怨等待；45 分钟趴着盼归
      setMoodFor(long ? "liedown" : "sad", 5000);
      const name = get().pet.profile.name;
      setBubble(pick(long ? REACT_SCENE.awayLong : REACT_SCENE.awayShort, name), 6000);
    },

    setLowPower: (v) => set({ lowPower: v }),
    setChatApp: (v) => set({ chatApp: v }),

    tickReminder: () => {
      const s = get();
      if (s.hidden || s.focus || s.reminder || s.showOnboarding) return;
      if (s.screenSharing) return;
      const now = Date.now();
      if (now < s.snoozeUntil) return;
      if (s.pet.health.mutedUntil && now < s.pet.health.mutedUntil) return;
      const interval = (isOffHours() ? BASE_INTERVAL_MS * 2 : BASE_INTERVAL_MS) / s.speedX;
      // 按开机时长计时：距上次提醒（或启动）满一个间隔即提醒，不再看活跃度
      if (now - reminderAnchor >= interval) {
        get().triggerReminder();
      }
    },

    demoBirthday: () => {
      get().fireConfetti("fireworks");
      setMoodFor("excited", 5000);
      setBubble(pick("birthday", get().pet.profile.name), 6000);
    },

    unlockAllSkins: () => {
      mutate((p) => {
        p.skins.unlocked = ["base", "night_owl", "workaholic", "health_guru", "winter"];
      });
      get().fireConfetti("stars");
      setBubble("我把所有形态都解锁啦，用工具条右上角换着玩～", 4600);
    },

    setSkin: (id) => {
      mutate((p) => {
        if (!p.skins.unlocked.includes(id)) p.skins.unlocked.push(id);
        p.skins.active = id;
      });
    },
  };
});
