import { usePetStore } from "@/state/usePetStore";
import { companionDay } from "@/utils/date";
import { SKIN_INFO } from "@/logic/evolution";
import { Heart, Cake } from "lucide-react";
import { isBirthdayToday } from "@/utils/date";

// 左上角：陪伴天数 + 当前形态徽章
export default function DayBadge() {
  const pet = usePetStore((s) => s.pet);
  if (!pet.profile.onboarded) return null;

  const day = companionDay(pet.profile.firstOpen);
  const birthday = isBirthdayToday(pet.profile.birthday);

  return (
    <div className="fixed top-4 left-4 z-40 animate-pop-in" data-interactive>
      <div className="px-1 py-1">
        <div className="flex items-center gap-2">
          {birthday ? (
            <Cake className="w-4 h-4 text-nose" />
          ) : (
            <Heart className="w-4 h-4 text-nose" fill="#FF9A9A" />
          )}
          <span className="font-body text-ink text-halo text-base">
            这是<b className="text-wood">{pet.profile.name}</b>陪你的第{" "}
            <b className="font-pixel text-base text-grass-dark">{day}</b> 天
          </span>
        </div>
        <div className="flex items-center gap-2 mt-1 text-sm font-body text-ink/80 text-halo">
          <span className="border-2 border-ink px-1.5">
            {SKIN_INFO[pet.skins.active].name}
          </span>
          <span>摸头 {pet.counters.petHead} · 专注 {pet.counters.focusSessions}</span>
        </div>
      </div>
    </div>
  );
}
