import { useEffect, useState } from "react";
import { Shield, X } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";

// 专注模式倒计时（25 分钟，可被 demo 加速）
export default function FocusOverlay() {
  const focus = usePetStore((s) => s.focus);
  const endFocus = usePetStore((s) => s.endFocus);
  const [remain, setRemain] = useState(0);

  useEffect(() => {
    if (!focus) return;
    const tick = () => {
      const left = focus.endsAt - Date.now();
      setRemain(Math.max(0, left));
      if (left <= 0) endFocus(true);
    };
    tick();
    const timer = setInterval(tick, 250);
    return () => clearInterval(timer);
  }, [focus, endFocus]);

  if (!focus) return null;

  const totalSec = Math.ceil(remain / 1000);
  const mm = String(Math.floor(totalSec / 60)).padStart(2, "0");
  const ss = String(totalSec % 60).padStart(2, "0");
  const progress = 1 - remain / focus.total;

  return (
    <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 animate-pop-in" data-interactive>
      <div className="px-2 py-1 flex items-center gap-3">
        <Shield className="w-5 h-5 text-grass-dark" />
        <div>
          <div className="font-body text-sm text-ink/70 text-halo leading-none mb-1">静默护卫中</div>
          <div className="font-pixel text-xl tracking-widest text-ink text-halo">{mm}:{ss}</div>
        </div>
        <div className="w-28 h-3 bg-ink/15 border-2 border-ink ml-2">
          <div className="h-full bg-grass" style={{ width: `${progress * 100}%` }} />
        </div>
        <button
          onClick={() => endFocus(false)}
          title="放弃专注"
          className="ml-1 text-ink/60 hover:text-berry transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
}
