// Electron 预加载注入的桌面能力；在普通浏览器中为 null
export interface DesktopActivity {
  idleSec: number; // 系统空闲秒数（powerMonitor.getSystemIdleTime）
  onBattery: boolean; // 是否使用电池供电（低能耗近似信号）
}

interface DesktopPetApi {
  isDesktop: boolean;
  setMouseIgnore: (ignore: boolean) => void;
  moveBy: (dx: number, dy: number) => void;
  onActivity?: (cb: (a: DesktopActivity) => void) => () => void;
}

export function getDesktopApi(): DesktopPetApi | null {
  return (window as unknown as { desktopPet?: DesktopPetApi }).desktopPet ?? null;
}

// 订阅桌面活动（系统空闲/电池）；返回取消订阅函数，浏览器预览下返回 null
export function onDesktopActivity(
  cb: (a: DesktopActivity) => void
): (() => void) | null {
  return getDesktopApi()?.onActivity?.(cb) ?? null;
}

// 透明/桌面样式的判定不依赖 preload（即使 preload 失败也能识别 Electron）
export const isDesktop = (): boolean =>
  !!getDesktopApi() || /electron/i.test(navigator.userAgent);

// 拖动小狗时移动整个悬浮窗；浏览器预览下无操作
export function moveWindowBy(dx: number, dy: number): void {
  getDesktopApi()?.moveBy(dx, dy);
}
