import { useState } from "react";
import {
  Bug,
  ChevronDown,
  ChevronUp,
  Bell,
  Cake,
  Sparkles,
  MonitorSmartphone,
  RotateCcw,
  PersonStanding,
  Rabbit,
  Undo2,
  MoveDown,
  Swords,
  MessageSquare,
  BatteryLow,
  Clock,
  Eye,
} from "lucide-react";
import { Mood } from "@/state/types";
import { usePetStore } from "@/state/usePetStore";
import { SKIN_INFO } from "@/logic/evolution";
import { SkinId } from "@/pixel/palette";

const SPEEDS = [1, 20, 120];

// Demo 调试面板：加速计时、手动触发各类事件、切换形态
export default function DebugPanel() {
  const [open, setOpen] = useState(false);
  const speedX = usePetStore((s) => s.speedX);
  const setSpeed = usePetStore((s) => s.setSpeed);
  const triggerReminder = usePetStore((s) => s.triggerReminder);
  const demoBirthday = usePetStore((s) => s.demoBirthday);
  const unlockAllSkins = usePetStore((s) => s.unlockAllSkins);
  const setSkin = usePetStore((s) => s.setSkin);
  const screenSharing = usePetStore((s) => s.screenSharing);
  const setScreenSharing = usePetStore((s) => s.setScreenSharing);
  const reset = usePetStore((s) => s.reset);
  const setMood = usePetStore((s) => s.setMood);
  const reactBattle = usePetStore((s) => s.reactBattle);
  const reactAlert = usePetStore((s) => s.reactAlert);
  const reactAway = usePetStore((s) => s.reactAway);
  const chatApp = usePetStore((s) => s.chatApp);
  const setChatApp = usePetStore((s) => s.setChatApp);
  const unlocked = usePetStore((s) => s.pet.skins.unlocked);
  const active = usePetStore((s) => s.pet.skins.active);

  const skins: SkinId[] = ["base", "night_owl", "workaholic", "health_guru", "winter"];

  const poses: { label: string; mood: Mood; icon: typeof Bell }[] = [
    { label: "站立", mood: "idle", icon: PersonStanding },
    { label: "奔跑", mood: "run", icon: Rabbit },
    { label: "回头", mood: "lookback", icon: Undo2 },
    { label: "趴下", mood: "liedown", icon: MoveDown },
    { label: "备战", mood: "battle", icon: Swords },
    { label: "警惕", mood: "alert", icon: Eye },
  ];

  return (
    <div className="fixed bottom-4 left-4 z-[55] font-body" data-interactive>
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex items-center gap-2 bg-ink text-paper px-3 py-2 border-[3px] border-ink shadow-pixel-sm"
      >
        <Bug className="w-4 h-4" />
        <span className="text-sm">Demo 调试台</span>
        {open ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
      </button>

      {open && (
        <div className="mt-2 w-[264px] bg-paper pixel-border p-3 space-y-3">
          <div>
            <div className="text-xs text-ink/70 mb-1">健康计时加速（演示用）</div>
            <div className="flex gap-1">
              {SPEEDS.map((s) => (
                <button
                  key={s}
                  onClick={() => setSpeed(s)}
                  className={`flex-1 text-sm py-1 border-2 border-ink ${
                    speedX === s ? "bg-grass text-white" : "bg-white text-ink"
                  }`}
                >
                  {s}×
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <DBtn icon={Bell} label="触发提醒" onClick={() => triggerReminder()} />
            <DBtn icon={Cake} label="过生日" onClick={demoBirthday} />
            <DBtn icon={Sparkles} label="解锁全部" onClick={unlockAllSkins} />
            <DBtn
              icon={MonitorSmartphone}
              label={screenSharing ? "共享中" : "共享屏幕"}
              onClick={() => setScreenSharing(!screenSharing)}
              active={screenSharing}
            />
          </div>

          <div>
            <div className="text-sm text-ink/70 mb-1">实时互动演示</div>
            <div className="grid grid-cols-2 gap-2">
              <DBtn icon={Swords} label="备战" onClick={() => reactBattle(chatApp)} />
              <DBtn
                icon={MessageSquare}
                label={chatApp ? "办公消息中" : "办公消息"}
                onClick={() => setChatApp(!chatApp)}
                active={chatApp}
              />
              <DBtn icon={BatteryLow} label="低电量警惕" onClick={reactAlert} />
              <DBtn icon={Clock} label="离开15分钟" onClick={() => reactAway(false)} />
              <DBtn icon={Clock} label="离开45分钟" onClick={() => reactAway(true)} />
            </div>
          </div>

          <div>
            <div className="text-sm text-ink/70 mb-1">动作演示</div>
            <div className="grid grid-cols-4 gap-1">
              {poses.map((p) => (
                <button
                  key={p.label}
                  onClick={() => setMood(p.mood, p.mood === "idle" ? 0 : 6000)}
                  className="flex flex-col items-center gap-0.5 text-xs py-1.5 border-2 border-ink bg-white text-ink hover:bg-fur"
                >
                  <p.icon className="w-4 h-4" /> {p.label}
                </button>
              ))}
            </div>
          </div>

          <div>
            <div className="text-sm text-ink/70 mb-1">切换形态</div>
            <div className="flex flex-wrap gap-1">
              {skins.map((id) => {
                const locked = !unlocked.includes(id);
                return (
                  <button
                    key={id}
                    disabled={locked}
                    onClick={() => setSkin(id)}
                    className={`text-xs px-2 py-1 border-2 border-ink ${
                      active === id ? "bg-grass text-white" : locked ? "bg-paper-dark text-ink/40" : "bg-white text-ink"
                    }`}
                  >
                    {SKIN_INFO[id].name}
                  </button>
                );
              })}
            </div>
          </div>

          <button
            onClick={reset}
            className="w-full flex items-center justify-center gap-2 bg-berry text-white text-sm py-1.5 border-2 border-ink"
          >
            <RotateCcw className="w-4 h-4" /> 重置全部数据
          </button>
        </div>
      )}
    </div>
  );
}

function DBtn({
  icon: Icon,
  label,
  onClick,
  active,
}: {
  icon: typeof Bell;
  label: string;
  onClick: () => void;
  active?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 text-sm px-2 py-1.5 border-2 border-ink ${
        active ? "bg-grass text-white" : "bg-white text-ink hover:bg-fur"
      }`}
    >
      <Icon className="w-4 h-4" /> {label}
    </button>
  );
}
