import { useEffect, useRef } from "react";
import { usePetStore } from "@/state/usePetStore";

interface P {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  life: number;
  shape: "sq" | "flower" | "star";
  rot: number;
}

const COLORS = ["#FF9A9A", "#E8C39E", "#7FB069", "#AEE1F0", "#C0392B", "#F5D06A", "#B7A2C7"];

// 像素粒子彩蛋层：烟花 / 花瓣 / 星星
export default function Confetti() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const confetti = usePetStore((s) => s.confetti);
  const particles = useRef<P[]>([]);
  const rafRef = useRef(0);

  useEffect(() => {
    if (!confetti) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.imageSmoothingEnabled = false;

    spawn(confetti.kind, particles.current, canvas.width, canvas.height);
    let last = performance.now();

    const tick = (now: number) => {
      const dt = Math.min(48, now - last) / 16;
      last = now;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const alive: P[] = [];
      for (const p of particles.current) {
        p.vy += 0.12 * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.rot += 0.1 * dt;
        p.life -= dt;
        if (p.life <= 0 || p.y > canvas.height + 20) continue;
        drawParticle(ctx, p);
        alive.push(p);
      }
      particles.current = alive;
      if (alive.length > 0) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
      }
    };
    cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, [confetti]);

  return (
    <canvas
      ref={canvasRef}
      className="pixelated fixed inset-0 z-[60] pointer-events-none"
    />
  );
}

function spawn(kind: string, arr: P[], w: number, h: number) {
  const rand = (a: number, b: number) => a + Math.random() * (b - a);
  if (kind === "fireworks") {
    for (let b = 0; b < 5; b++) {
      const cx = rand(w * 0.2, w * 0.8);
      const cy = rand(h * 0.15, h * 0.5);
      for (let i = 0; i < 40; i++) {
        const ang = (Math.PI * 2 * i) / 40;
        const sp = rand(2, 6);
        arr.push({
          x: cx, y: cy, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp,
          size: rand(4, 8), color: COLORS[i % COLORS.length], life: rand(40, 70),
          shape: "sq", rot: 0,
        });
      }
    }
  } else if (kind === "petals") {
    for (let i = 0; i < 70; i++) {
      arr.push({
        x: rand(0, w), y: rand(-h, 0), vx: rand(-1, 1), vy: rand(1, 3),
        size: rand(6, 12), color: COLORS[Math.floor(rand(0, COLORS.length))],
        life: rand(120, 200), shape: "flower", rot: rand(0, 6),
      });
    }
  } else {
    for (let i = 0; i < 50; i++) {
      arr.push({
        x: rand(0, w), y: rand(h * 0.5, h), vx: rand(-1, 1), vy: rand(-5, -2),
        size: rand(5, 10), color: COLORS[Math.floor(rand(0, COLORS.length))],
        life: rand(60, 100), shape: "star", rot: 0,
      });
    }
  }
}

function drawParticle(ctx: CanvasRenderingContext2D, p: P) {
  ctx.fillStyle = p.color;
  const s = Math.round(p.size);
  const x = Math.round(p.x);
  const y = Math.round(p.y);
  if (p.shape === "sq") {
    ctx.fillRect(x, y, s, s);
  } else if (p.shape === "flower") {
    const u = Math.max(2, Math.round(s / 3));
    ctx.fillRect(x, y - u, u, u);
    ctx.fillRect(x, y + u, u, u);
    ctx.fillRect(x - u, y, u, u);
    ctx.fillRect(x + u, y, u, u);
    ctx.fillStyle = "#FFF6D8";
    ctx.fillRect(x, y, u, u);
  } else {
    const u = Math.max(2, Math.round(s / 3));
    ctx.fillRect(x, y, u, u * 3);
    ctx.fillRect(x - u, y + u, u * 3, u);
  }
}
