export function todayISO(d = new Date()): string {
  return d.toISOString().slice(0, 10);
}

export function daysBetween(fromISO: string, toISO: string): number {
  const a = new Date(fromISO + "T00:00:00");
  const b = new Date(toISO + "T00:00:00");
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

// 陪伴第 N 天（首次打开当天为第 1 天）
export function companionDay(firstOpenISO: string): number {
  return Math.max(1, daysBetween(firstOpenISO, todayISO()) + 1);
}

// 生日格式统一为 MM-DD 比较
export function toMMDD(birthday: string): string {
  if (!birthday) return "";
  if (birthday.length === 5) return birthday; // 已是 MM-DD
  return birthday.slice(5, 10);
}

export function isBirthdayToday(birthday: string, d = new Date()): boolean {
  const mmdd = toMMDD(birthday);
  if (!mmdd) return false;
  const cur = `${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate()
  ).padStart(2, "0")}`;
  return mmdd === cur;
}

export function isLateNight(d = new Date()): boolean {
  const h = d.getHours();
  return h >= 0 && h < 5;
}

// 工作时间外（19:00 - 次日 08:00）→ 提醒间隔延长
export function isOffHours(d = new Date()): boolean {
  const h = d.getHours();
  return h >= 19 || h < 8;
}

export function hourNow(d = new Date()): number {
  return d.getHours();
}
