import { Trophy, BookOpen, Timer, EyeOff, Eye } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";
import { isDesktop } from "@/utils/desktop";

// 右侧竖排功能工具条（桌面悬浮模式改为底部横排）
export default function Toolbar() {
  const setScorecard = usePetStore((s) => s.setScorecard);
  const setDiaryOpen = usePetStore((s) => s.setDiaryOpen);
  const startFocus = usePetStore((s) => s.startFocus);
  const toggleHidden = usePetStore((s) => s.toggleHidden);
  const hidden = usePetStore((s) => s.hidden);
  const onboarded = usePetStore((s) => s.pet.profile.onboarded);
  const focus = usePetStore((s) => s.focus);

  if (!onboarded) return null;

  const desktop = isDesktop();

  const Btn = ({
    icon: Icon,
    label,
    onClick,
    active,
  }: {
    icon: typeof Trophy;
    label: string;
    onClick: () => void;
    active?: boolean;
  }) => (
    <button
      onClick={onClick}
      title={label}
      className={`group relative flex items-center justify-center btn-ghost ${
        desktop ? "w-8 h-8" : "w-11 h-11"
      } ${active ? "text-white" : "text-ink"}`}
      style={active ? { background: "#7FB069" } : undefined}
    >
      <Icon className={desktop ? "w-4 h-4" : "w-5 h-5"} />
      <span
        className={`absolute whitespace-nowrap text-ink font-body text-sm px-2 py-1 text-halo opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity ${
          desktop ? "bottom-full mb-1 left-1/2 -translate-x-1/2" : "right-full mr-2"
        }`}
      >
        {label}
      </span>
    </button>
  );

  return (
    <div
      className={
        desktop
          ? "fixed bottom-2 left-1/2 -translate-x-1/2 z-40 flex flex-row gap-1.5"
          : "fixed top-1/2 -translate-y-1/2 right-4 z-40 flex flex-col gap-2"
      }
      data-interactive
    >
      <Btn icon={Timer} label="专注模式" onClick={startFocus} active={!!focus} />
      <Btn icon={Trophy} label="健康战绩" onClick={() => setScorecard(true)} />
      <Btn icon={BookOpen} label="像素狗日记" onClick={() => setDiaryOpen(true)} />
      <Btn
        icon={hidden ? Eye : EyeOff}
        label={hidden ? "唤回小狗" : "老板键 (Ctrl+Shift+Q)"}
        onClick={toggleHidden}
      />
    </div>
  );
}
