import { useEffect } from "react";
import { usePetStore } from "@/state/usePetStore";
import { isDesktop, onDesktopActivity } from "@/utils/desktop";

// —— 实时互动状态检测 ——
// 备战：短时间内键鼠/滚轮高频 → 预览页按事件频率真实统计；桌面端按“持续零空闲”近似
// 警惕：低电量/电池供电（桌面 powerMonitor；预览页用调试开关）
// 离开：系统空闲 15 / 45 分钟（桌面 powerMonitor；预览页按最近一次输入推算）
const EVAL_MS = 2000; // 评估节奏
const BATTLE_WINDOW_MS = 3000; // 高频统计窗口
const BATTLE_THRESHOLD = 22; // 预览页：3 秒内 ≥22 次输入判为高频
const BATTLE_ACTIVE_MS = 24_000; // 桌面：持续活跃满 24s 判为“拼命三郎”
const BATTLE_COOLDOWN_MS = 90_000; // 备战冷却，避免刷屏
const AWAY_SHORT_MS = 15 * 60 * 1000;
const AWAY_LONG_MS = 45 * 60 * 1000;

export function useInteractionStates() {
  useEffect(() => {
    const desktop = isDesktop();

    // 高频输入统计（预览页真实事件）
    const inputTimes: number[] = [];
    let lastActive = Date.now();
    const onInput = () => {
      const now = Date.now();
      inputTimes.push(now);
      lastActive = now;
    };
    window.addEventListener("keydown", onInput);
    window.addEventListener("pointerdown", onInput);
    window.addEventListener("wheel", onInput, { passive: true });

    // 桌面活动（系统空闲秒数 + 是否电池供电）
    let idleSec = 0;
    let onBattery = false;
    const unsub = onDesktopActivity((a) => {
      idleSec = a.idleSec;
      onBattery = a.onBattery;
      usePetStore.getState().setLowPower(a.onBattery);
    });

    // 触发去抖状态
    let lastBattleAt = 0;
    let activeStreakMs = 0;
    let awayShortFired = false;
    let awayLongFired = false;
    let prevLowPower = false;

    const timer = setInterval(() => {
      const s = usePetStore.getState();
      const now = Date.now();
      const speed = s.speedX || 1;

      // —— 备战：高频输入 ——
      while (inputTimes.length && now - inputTimes[0] > BATTLE_WINDOW_MS) inputTimes.shift();
      let frenzy = false;
      if (desktop) {
        // 桌面拿不到全局键鼠，用“持续零空闲”近似高强度工作
        if (idleSec <= 1) activeStreakMs += EVAL_MS;
        else activeStreakMs = 0;
        if (activeStreakMs >= BATTLE_ACTIVE_MS) frenzy = true;
      } else {
        if (inputTimes.length >= BATTLE_THRESHOLD) frenzy = true;
      }
      if (frenzy && now - lastBattleAt > BATTLE_COOLDOWN_MS) {
        s.reactBattle(s.chatApp);
        lastBattleAt = now;
        activeStreakMs = 0;
        inputTimes.length = 0;
      }

      // —— 离开：系统空闲时长 ——
      const idleMs = desktop ? idleSec * 1000 : now - lastActive;
      const shortMs = AWAY_SHORT_MS / speed;
      const longMs = AWAY_LONG_MS / speed;
      if (idleMs >= longMs) {
        if (!awayLongFired) {
          s.reactAway(true);
          awayLongFired = true;
          awayShortFired = true;
        }
      } else if (idleMs >= shortMs) {
        if (!awayShortFired) {
          s.reactAway(false);
          awayShortFired = true;
        }
      } else {
        awayShortFired = false;
        awayLongFired = false;
      }

      // —— 警惕：低电量/低能耗（进入时触发一次）——
      const lowPower = desktop ? onBattery : s.lowPower;
      if (lowPower && !prevLowPower) s.reactAlert();
      prevLowPower = lowPower;
    }, EVAL_MS);

    return () => {
      window.removeEventListener("keydown", onInput);
      window.removeEventListener("pointerdown", onInput);
      window.removeEventListener("wheel", onInput);
      unsub?.();
      clearInterval(timer);
    };
  }, []);
}

// 空依赖 effect 在 Fast Refresh 下不会重跑，改动本文件后自动整页刷新以重挂监听
if (import.meta.hot) {
  import.meta.hot.accept(() => window.location.reload());
}
