import { DogFrame } from "./dogModel";
import { SkinId } from "./palette";
import { Mood } from "@/state/types";

export interface AnimInput {
  mood: Mood;
  tMs: number;
  skin: SkinId;
  look: number; // -1..1 光标水平方向
  lookY: number; // -1..1 光标垂直方向
  tsundereIdle: boolean; // 傲娇：闲置主动伸头
}

export interface AnimOutput {
  frame: DogFrame;
  // 整体变换：x 左右摇摆，y<0 起跳；scaleX 转圈绕竖轴，scaleY 倒立绕横轴
  offset: { x: number; y: number; scaleX?: number; scaleY?: number };
}

// 眨眼：约每 5 秒一次，持续 ~160ms
function isBlinking(tMs: number): boolean {
  const phase = tMs % 5000;
  return phase < 160;
}

// 闲置时偶尔吐舌头（呆萌）：每 ~9s 冒出 ~0.9s
function isIdleTongue(tMs: number): boolean {
  const phase = tMs % 9000;
  return phase > 7900 && phase < 8800;
}

export function computeFrame(input: AnimInput): AnimOutput {
  const { mood, tMs, skin, look, lookY, tsundereIdle } = input;
  const t = tMs / 1000;
  const breathe = Math.sin(t * 1.6); // -1..1

  const base: DogFrame = {
    eye: "open",
    mouth: "smile",
    legKick: 0,
    earTilt: 0,
    look,
    lookY,
    tailWag: Math.sin(t * 4) * 0.6,
    blush: false,
    skin,
    pose: "stand",
  };
  // 静息时的轻微呼吸下沉
  const settle = { x: 0, y: breathe > 0.4 ? 1 : 0 };

  switch (mood) {
    case "happy": {
      // 摸头享受：轻快上下蹦跶 + 微微左右摇摆（线条小狗的开心节奏），耳朵随节拍弹动
      const hop = Math.abs(Math.sin(t * 6));
      return {
        frame: { ...base, eye: "happy", mouth: "smile", blush: true, earTilt: 0.3 + hop * 0.4, tailWag: Math.sin(t * 12) },
        offset: { x: Math.sin(t * 6), y: -hop * 2 },
      };
    }
    case "excited": {
      // 兴奋/健康提醒：快速蹦跳 + 左右摇摆，耳朵飞起
      const hop = Math.abs(Math.sin(t * 9));
      return {
        frame: {
          ...base,
          eye: "wide",
          mouth: "open",
          earTilt: 0.7,
          legKick: (Math.sin(t * 12) + 1) / 2,
          tailWag: Math.sin(t * 16),
        },
        offset: { x: Math.sin(t * 7) * 1.5, y: -hop * 2 },
      };
    }
    case "lick": // 舔碗
      return {
        frame: { ...base, eye: "happy", mouth: "tongue", tailWag: Math.sin(t * 12) },
        offset: { x: 0, y: -Math.abs(Math.sin(t * 5)) },
      };
    case "sleep": { // 睡觉：蜷成一团贴地，缓慢的呼吸起伏，耳朵放松耷下
      const slow = Math.sin(t * 0.9); // 比平时更慢的呼吸
      return {
        frame: { ...base, pose: "sleep", eye: "closed", mouth: "neutral", earTilt: -0.8, tailWag: 0, blush: true },
        offset: { x: 0, y: slow > 0 ? 1 : 0 },
      };
    }
    case "thumbsup": { // 打卡表扬：小雀跃
      const hop = Math.abs(Math.sin(t * 5));
      return {
        frame: { ...base, eye: "happy", mouth: "grin", blush: true, earTilt: 0.5 + hop * 0.2 },
        offset: { x: 0, y: -hop },
      };
    }
    case "eyeroll": // 贪睡翻白眼
      return { frame: { ...base, eye: "roll", mouth: "flat", earTilt: -0.4 }, offset: settle };
    case "sad": // 卖惨/幽怨：耷拉不动
      return { frame: { ...base, eye: "sad", mouth: "flat", earTilt: -0.9, tailWag: 0 }, offset: { x: 0, y: 0 } };
    case "focus": // 专注护卫，坚毅：轻微左右张望
      return {
        frame: { ...base, eye: "open", mouth: "grin", earTilt: 0.3, tailWag: Math.sin(t * 2) * 0.3 },
        offset: { x: Math.sin(t * 1.5) * 0.6, y: settle.y },
      };
    case "run": {
      // 奔跑：四脚离地，快速切换帧 + 大幅上下弹跳 + 左右摆动，吐舌
      const kick = Math.floor(t * 9) % 2; // 快速交替腿部相位
      const hop = Math.abs(Math.sin(t * 9)); // 0..1
      return {
        frame: {
          ...base,
          pose: "run",
          eye: "wide",
          mouth: "tongue",
          earTilt: 0.6,
          legKick: kick,
          tailWag: Math.sin(t * 16),
        },
        offset: { x: Math.sin(t * 9), y: -hop * 2 }, // 起跳 0..2 px（封顶 2，防止裁耳）
      };
    }
    case "lookback": { // 回头张望：身体不动，头转向侧面
      const dir = Math.abs(look) > 0.1 ? look : Math.sin(t * 0.9);
      return {
        frame: {
          ...base,
          pose: "lookback",
          eye: "open",
          mouth: "smile",
          look: dir,
          tailWag: Math.sin(t * 5) * 0.7,
        },
        offset: { x: 0, y: breathe > 0.4 ? 1 : 0 },
      };
    }
    case "liedown": { // 趴下休息：慵懒，睁着圆眼看人，偶尔眨眼/摇尾
      const eye = isBlinking(tMs) ? "blink" : "open";
      return {
        frame: {
          ...base,
          pose: "liedown",
          eye,
          mouth: "smile",
          earTilt: -0.2, // 趴着耳朵稍放松但仍支棱
          tailWag: Math.sin(t * 3) * 0.5,
          blush: true,
        },
        offset: { x: 0, y: breathe > 0 ? 1 : 0 },
      };
    }
    case "sit": { // 坐下发呆：安静地坐着，偶尔眨眼/耳朵抽动/歪头
      const eye = isBlinking(tMs) ? "blink" : "open";
      const twitchPhase = tMs % 4200;
      const earTwitch = twitchPhase < 260 ? Math.sin((twitchPhase / 260) * Math.PI * 3) * 0.6 : 0;
      const tiltPhase = tMs % 7000;
      const headTilt = tiltPhase > 5200 && tiltPhase < 6400 ? (Math.floor(tMs / 7000) % 2 ? 1 : -1) : 0;
      return {
        frame: {
          ...base,
          pose: "sit",
          eye,
          mouth: "smile",
          earTilt: 0.25 + earTwitch,
          headTilt,
          tailWag: Math.sin(t * 3) * 0.4,
        },
        offset: settle,
      };
    }
    case "stretch": { // 伸懒腰打哈欠：前段张大嘴闭眼打哈欠，后段收回眯眼满足
      const phase = (tMs % 2000) / 2000;
      const yawning = phase < 0.62;
      return {
        frame: {
          ...base,
          pose: "stretch",
          eye: yawning ? "closed" : "happy",
          mouth: yawning ? "open" : "smile",
          earTilt: -0.4,
          tailWag: 0.2,
          blush: !yawning,
        },
        offset: { x: 0, y: 0 },
      };
    }
    case "scratch": { // 抬后腿挠耳：后腿快速抓挠抖动，享受表情吐舌
      const kick = Math.floor(t * 12) % 2; // 快速抓挠相位
      return {
        frame: {
          ...base,
          pose: "scratch",
          eye: "happy",
          mouth: "tongue",
          legKick: kick,
          earTilt: -0.3,
          tailWag: Math.sin(t * 6) * 0.4,
        },
        offset: { x: 0, y: 0 },
      };
    }
    case "sniff": { // 低头嗅地：头压低，视线随嗅探左右缓移，耳朵前耷
      const sway = Math.sin(t * 2) * 0.6;
      return {
        frame: {
          ...base,
          pose: "sniff",
          eye: "open",
          mouth: "neutral",
          earTilt: -0.5,
          look: sway,
          tailWag: Math.sin(t * 4) * 0.35,
        },
        offset: { x: 0, y: 0 },
      };
    }
    case "handstand": { // 倒立：整体上下翻转，靠头/前爪支地，轻微左右晃动保持平衡，得意吐舌
      const wobble = Math.sin(t * 3) * 0.8;
      return {
        frame: { ...base, eye: "happy", mouth: "tongue", earTilt: 0.5, blush: true, tailWag: Math.sin(t * 5) * 0.6 },
        offset: { x: wobble, y: 0, scaleY: -1 },
      };
    }
    case "spin": { // 原地转圈：绕竖轴翻转（scaleX 在 1→0→-1 摆动模拟转身）+ 欢快小跳
      const spin = Math.cos(t * 5.2);
      const hop = Math.abs(Math.sin(t * 5.2));
      return {
        frame: { ...base, eye: "wide", mouth: "tongue", earTilt: 0.7, tailWag: Math.sin(t * 16) },
        offset: { x: 0, y: -hop, scaleX: spin },
      };
    }
    case "battle": { // 备战：前倾蓄力发抖、瞪眼竖耳，眼神盯着光标（你的战场）
      const tremble = Math.sin(t * 34) * 0.4; // 高频微抖，蓄势待发
      return {
        frame: {
          ...base,
          pose: "battle",
          eye: "wide",
          mouth: "grin",
          earTilt: 0.9,
          tailWag: Math.sin(t * 14),
        },
        offset: { x: tremble, y: 0 },
      };
    }
    case "alert": { // 警惕：站立扭向屏幕外侧盯梢，竖耳瞪眼，缓慢左右扫视
      const scan = Math.sin(t * 1.4) * 0.35;
      return {
        frame: {
          ...base,
          pose: "alert",
          eye: "wide",
          mouth: "flat",
          earTilt: 1,
          look: 1, // 视线钉在屏幕外侧
          headTilt: 1,
          tailWag: Math.sin(t * 2) * 0.2,
        },
        offset: { x: scan, y: settle.y },
      };
    }
    case "idle":
    default: {
      const tongue = isIdleTongue(tMs);
      const eye: DogFrame["eye"] = isBlinking(tMs) ? "blink" : tongue ? "happy" : "open";
      const baseEar = tsundereIdle ? 0.7 + Math.sin(t * 3) * 0.2 : Math.sin(t * 1.2) * 0.2;
      // 耳朵抽动：每 ~4.5s 快速抖一下 ~260ms
      const twitchPhase = tMs % 4500;
      const earTwitch = twitchPhase < 260 ? Math.sin((twitchPhase / 260) * Math.PI * 3) * 0.6 : 0;
      // 偶尔歪头：每 ~8s 歪 ~1.4s，左右交替
      const tiltPhase = tMs % 8000;
      const headTilt = tiltPhase > 6000 && tiltPhase < 7400 ? (Math.floor(tMs / 8000) % 2 ? 1 : -1) : 0;
      // 闲置也有生气：每 ~6s 自发小蹦一下
      const hopPhase = tMs % 6000;
      const idleHop = hopPhase < 700 ? Math.sin((hopPhase / 700) * Math.PI) * 2 : 0;
      return {
        frame: {
          ...base,
          eye,
          earTilt: baseEar + earTwitch,
          headTilt,
          mouth: tongue ? "tongue" : "smile",
          blush: tongue,
        },
        offset: { x: 0, y: idleHop > 0 ? -idleHop : settle.y },
      };
    }
  }
}
