export const HEALTH_LABEL: Record<HealthType, string> = {
  water: "喝水",
  pee: "撒尿",
  sit: "久坐",
};

function format(text: string, name: string, day?: number): string {
  let result = text.replace(/\[狗名\]/g, name || "小狗");
  if (day !== undefined) {
    result = result.replace(/\[天数\]/g, String(day));
  }
  return result;
}

export function pick(scene: Scene, name: string, day?: number): string {
  const arr = POOL[scene];
  const t = arr[Math.floor(Math.random() * arr.length)];
  return format(t, name, day);
}

export function pickHealth(type: HealthType, name: string): string {
  const arr = HEALTH_POOL[type];
  const t = arr[Math.floor(Math.random() * arr.length)];
  return format(t, name);
}
