import { useEffect } from "react";
import { Dog } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";
import { useHotkeys } from "@/hooks/useHotkeys";
import { useUptimeReminder } from "@/hooks/useUptimeReminder";
import { useInteractionStates } from "@/hooks/useInteractionStates";
import { useDesktopMouse } from "@/hooks/useDesktopMouse";
import { isDesktop } from "@/utils/desktop";
import DogCanvas from "@/components/DogCanvas";
import DayBadge from "@/components/DayBadge";
import Toolbar from "@/components/Toolbar";
import OnboardingModal from "@/components/OnboardingModal";
import FocusOverlay from "@/components/FocusOverlay";
import HealthReminder from "@/components/HealthReminder";
import Scorecard from "@/components/Scorecard";
import DiaryModal from "@/components/DiaryModal";
import Confetti from "@/components/Confetti";
import DebugPanel from "@/components/DebugPanel";

export default function Home() {
  const init = usePetStore((s) => s.init);
  const hidden = usePetStore((s) => s.hidden);
  const toggleHidden = usePetStore((s) => s.toggleHidden);

  useHotkeys();
  useUptimeReminder();
  useInteractionStates();
  useDesktopMouse();

  useEffect(() => {
    init();
  }, [init]);

  const desktop = isDesktop();

  return (
    <main className="fixed inset-0 overflow-hidden">
      {/* 演示场景说明：桌面悬浮模式下隐藏，避免遮挡真实桌面 */}
      {!desktop && (
        <div className="pointer-events-none fixed bottom-4 left-1/2 -translate-x-1/2 z-0 text-center">
          <p className="font-body text-ink/35 text-sm">
            把我拖到顺手的角落 · 单击头摸头 · 连点三下开启专注
          </p>
        </div>
      )}

      {/* 桌面陪伴层：老板键隐藏时整体收起 */}
      {!hidden && (
        <>
          {!desktop && <DayBadge />}
          <Toolbar />
          <DogCanvas />
        </>
      )}

      {/* 老板键隐藏后的低调唤回入口 */}
      {hidden && (
        <button
          onClick={toggleHidden}
          data-interactive
          title="唤回小狗 (Ctrl+Shift+Q)"
          className="fixed bottom-4 right-4 z-40 flex items-center gap-2 bg-paper/80 hover:bg-paper text-ink/60 hover:text-ink border-2 border-ink/30 hover:border-ink px-3 py-2 text-sm font-body transition-colors"
        >
          <Dog className="w-4 h-4" />
          唤回小狗
        </button>
      )}

      {/* 全局浮层：引导 / 专注 / 弹窗 / 彩蛋 / 调试台 */}
      <OnboardingModal />
      <FocusOverlay />
      <HealthReminder />
      <Scorecard />
      <DiaryModal />
      <Confetti />
      {!desktop && <DebugPanel />}
    </main>
  );
}
