import { useEffect } from "react";
import { getDesktopApi, isDesktop } from "@/utils/desktop";

export function useDesktopMouse() {
  useEffect(() => {
    if (!isDesktop()) return;
    document.body.classList.add("desktop");

    const api = getDesktopApi();
    if (!api) {
      return () => document.body.classList.remove("desktop");
    }

    let ignoring = true;
    let pressed = false;
    api.setMouseIgnore(true);

    const setIgnore = (next: boolean) => {
      if (next !== ignoring) {
        ignoring = next;
        api.setMouseIgnore(next);
      }
    };

    let lastMouseX = 0;
    let lastMouseY = 0;
    let ignoreTimer: ReturnType<typeof setTimeout> | null = null;

    const checkInteractive = () => {
      if (pressed) {
        setIgnore(false);
        return;
      }
      const elements = document.querySelectorAll("[data-interactive]");
      let interactive = false;
      for (const el of elements) {
        const rect = el.getBoundingClientRect();
        if (
          lastMouseX >= rect.left &&
          lastMouseX <= rect.right &&
          lastMouseY >= rect.top &&
          lastMouseY <= rect.bottom
        ) {
          interactive = true;
          break;
        }
      }
      if (interactive) {
        if (ignoreTimer) {
          clearTimeout(ignoreTimer);
          ignoreTimer = null;
        }
        setIgnore(false);
      } else {
        if (!ignoreTimer) {
          ignoreTimer = setTimeout(() => {
            setIgnore(true);
            ignoreTimer = null;
          }, 200);
        }
      }
    };

    let rafId: number;
    const poll = () => {
      checkInteractive();
      rafId = requestAnimationFrame(poll);
    };

    poll();

    const onMouseMove = (e: MouseEvent) => {
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
    };

    const onPointerDown = () => {
      pressed = true;
      setIgnore(false);
    };

    const onPointerUp = () => {
      pressed = false;
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("pointermove", onMouseMove);
    window.addEventListener("pointerdown", onPointerDown, true);
    window.addEventListener("pointerup", onPointerUp, true);
    window.addEventListener("pointercancel", onPointerUp, true);

    return () => {
      cancelAnimationFrame(rafId);
      if (ignoreTimer) clearTimeout(ignoreTimer);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("pointermove", onMouseMove);
      window.removeEventListener("pointerdown", onPointerDown, true);
      window.removeEventListener("pointerup", onPointerUp, true);
      window.removeEventListener("pointercancel", onPointerUp, true);
      document.body.classList.remove("desktop");
    };
  }, []);
}

if (import.meta.hot) {
  import.meta.hot.accept(() => window.location.reload());
}
