import { Droplet, Footprints, Armchair } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";
import { HEALTH_LABEL } from "@/logic/copy";
import { HealthType } from "@/state/types";
import { isDesktop } from "@/utils/desktop";

const ICONS: Record<HealthType, typeof Droplet> = {
  water: Droplet,
  pee: Footprints,
  sit: Armchair,
};

export default function HealthReminder() {
  const reminder = usePetStore((s) => s.reminder);
  const healthCheck = usePetStore((s) => s.healthCheck);
  const snooze = usePetStore((s) => s.snooze);
  const desktop = isDesktop();

  if (!reminder) return null;
  const Icon = ICONS[reminder.type];

  return (
    <div
      className={
        desktop
          ? "fixed bottom-[110px] right-[30px] z-[65] animate-pop-in w-[160px] pointer-events-none"
          : "fixed bottom-6 left-1/2 -translate-x-1/2 z-[65] w-[420px] max-w-[92vw] animate-pop-in"
      }
      data-interactive={!desktop}
    >
      <div className="bg-paper pixel-border p-2">
        <div className="flex items-center gap-2 mb-1.5">
          <span className="border-[3px] border-ink p-1 shadow-pixel-sm bg-sky/70">
            <Icon className={desktop ? "w-4 h-4 text-ink" : "w-5 h-5 text-ink"} />
          </span>
          <span className={desktop ? "font-display text-sm text-ink" : "font-display text-xl text-ink"}>
            {HEALTH_LABEL[reminder.type]}提醒
          </span>
        </div>
        <p
          className={
            desktop
              ? "font-body text-ink text-xs leading-snug mb-2"
              : "font-body text-ink text-base leading-relaxed mb-4"
          }
        >
          {reminder.text}
        </p>
        <div className={desktop ? "flex gap-2" : "flex gap-3"}>
          <button
            onClick={healthCheck}
            className={
              desktop
                ? "flex-1 btn-ghost text-ink font-display text-xs py-1 pointer-events-auto"
                : "flex-1 btn-ghost text-ink font-display text-lg py-2"
            }
            data-interactive
          >
            {desktop ? "好" : "好的，这就去！"}
          </button>
          <button
            onClick={snooze}
            className={
              desktop
                ? "flex-1 btn-ghost text-ink/80 font-display text-xs py-1 pointer-events-auto"
                : "flex-1 btn-ghost text-ink/80 font-display text-lg py-2"
            }
            data-interactive
          >
            {desktop ? "稍后" : "5 分钟后再叫"}
          </button>
        </div>
      </div>
    </div>
  );
}
