import { useEffect, useState } from "react";
import { Download, X } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";
import { buildScorecard } from "@/logic/scorecard";

// 健康战绩卡片弹窗，可导出 PNG
export default function Scorecard() {
  const open = usePetStore((s) => s.scorecardOpen);
  const setOpen = usePetStore((s) => s.setScorecard);
  const pet = usePetStore((s) => s.pet);
  const [url, setUrl] = useState("");

  useEffect(() => {
    if (!open) return;
    // 等字体加载完再绘制，保证文字清晰
    const draw = () => setUrl(buildScorecard(pet).toDataURL("image/png"));
    if (document.fonts?.ready) document.fonts.ready.then(draw);
    else draw();
  }, [open, pet]);

  if (!open) return null;

  const download = () => {
    const a = document.createElement("a");
    a.href = url;
    a.download = `${pet.profile.name}-健康战绩.png`;
    a.click();
  };

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-ink/40"
      data-interactive
      onClick={() => setOpen(false)}
    >
      <div className="animate-pop-in" onClick={(e) => e.stopPropagation()}>
        {url && (
          <img src={url} alt="健康战绩" className="pixelated w-[300px] shadow-pixel-lg" />
        )}
        <div className="flex gap-3 mt-4 justify-center">
          <button
            onClick={download}
            className="flex items-center gap-2 bg-grass hover:bg-grass-dark text-white font-display text-lg px-4 py-2 border-[3px] border-ink shadow-pixel active:translate-y-[2px] transition-transform"
          >
            <Download className="w-5 h-5" /> 保存图片
          </button>
          <button
            onClick={() => setOpen(false)}
            className="flex items-center gap-2 bg-paper hover:bg-paper-dark text-ink font-display text-lg px-4 py-2 border-[3px] border-ink shadow-pixel active:translate-y-[2px] transition-transform"
          >
            <X className="w-5 h-5" /> 关闭
          </button>
        </div>
      </div>
    </div>
  );
}
