import { X, PenLine } from "lucide-react";
import { usePetStore } from "@/state/usePetStore";
import { DiaryEntry } from "@/state/types";

const MOOD_EMOJI: Record<DiaryEntry["mood"], string> = {
  happy: "(◕ᴥ◕)",
  proud: "(￣^￣)ゞ",
  angry: "(╬ಠ益ಠ)",
  tired: "(-ᴥ-)zzz",
  calm: "(・ᴥ・)",
};

// 像素狗日记本
export default function DiaryModal() {
  const open = usePetStore((s) => s.diaryOpen);
  const setOpen = usePetStore((s) => s.setDiaryOpen);
  const diary = usePetStore((s) => s.pet.diary);
  const writeDiary = usePetStore((s) => s.writeDiary);

  if (!open) return null;
  const entries = [...diary].reverse();

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-ink/40" data-interactive onClick={() => setOpen(false)}>
      <div
        className="bg-paper pixel-border w-[440px] max-w-[92vw] max-h-[80vh] flex flex-col animate-pop-in"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-5 py-3 bg-wood border-b-[3px] border-ink">
          <h2 className="font-display text-2xl text-paper">像素狗日记</h2>
          <button onClick={() => setOpen(false)} className="text-paper hover:text-nose">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="overflow-y-auto p-4 space-y-3 flex-1">
          {entries.length === 0 && (
            <p className="font-body text-ink/60 text-center py-10">
              还没有日记呢。到了下午 4:30，我会把今天写下来～
            </p>
          )}
          {entries.map((d, i) => (
            <div key={i} className="bg-white border-[3px] border-ink p-3 shadow-pixel-sm">
              <div className="flex items-center justify-between mb-1">
                <span className="font-pixel text-sm text-wood">{d.date}</span>
                <span className="font-body text-ink/70 text-base">{MOOD_EMOJI[d.mood]}</span>
              </div>
              <p className="font-body text-ink text-base leading-relaxed">{d.text}</p>
            </div>
          ))}
        </div>

        <div className="p-4 border-t-[3px] border-ink">
          <button
            onClick={writeDiary}
            className="w-full flex items-center justify-center gap-2 bg-grass hover:bg-grass-dark text-white font-display text-lg py-2 border-[3px] border-ink shadow-pixel active:translate-y-[2px] transition-transform"
          >
            <PenLine className="w-5 h-5" /> 写今天的日记
          </button>
        </div>
      </div>
    </div>
  );
}
