import { PetState } from "./types";

const KEY = "puppy:v1";
const VERSION = 1;

export function defaultState(): PetState {
  const today = new Date().toISOString().slice(0, 10);
  return {
    version: VERSION,
    profile: { name: "小狗", gender: "boy", birthday: "", firstOpen: today, onboarded: false },
    counters: {
      petHead: 0,
      petChin: 0,
      focusSessions: 0,
      bossKey: 0,
      lateNightOpens: 0,
      birthdayPets: 0,
      birthdayPetsDate: "",
    },
    health: {
      todayDate: today,
      todayTypes: [],
      totalChecks: 0,
      streakDays: 0,
      lastCheckDate: "",
      snoozeCount: 0,
      mutedUntil: null,
      lastReminderType: null,
      lastDiaryDate: "",
      activeMsAccum: 0,
    },
    weights: { nightOwl: 0, tsundere: 0, alert: 0, workaholic: 0, healthGuru: 0 },
    skins: { active: "base", unlocked: ["base"] },
    diary: [],
    position: { x: -1, y: -1 }, // -1 表示尚未初始化，落位到右上角
  };
}

// 用默认值补齐缺失字段，容错旧数据
function merge<T>(base: T, saved: Partial<T> | undefined): T {
  if (!saved || typeof saved !== "object") return base;
  const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  for (const k of Object.keys(base as Record<string, unknown>)) {
    const b = (base as Record<string, unknown>)[k];
    const s = (saved as Record<string, unknown>)[k];
    if (b && typeof b === "object" && !Array.isArray(b)) {
      out[k] = merge(b, s as Partial<typeof b>);
    } else if (s !== undefined) {
      out[k] = s;
    }
  }
  return out as T;
}

export function loadState(): PetState {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return defaultState();
    const parsed = JSON.parse(raw) as Partial<PetState>;
    return merge(defaultState(), parsed);
  } catch {
    return defaultState();
  }
}

export function saveState(state: PetState) {
  try {
    localStorage.setItem(KEY, JSON.stringify(state));
  } catch {
    /* 忽略持久化失败（隐私模式等） */
  }
}

export function resetState() {
  try {
    localStorage.removeItem(KEY);
  } catch {
    /* noop */
  }
}
