import { buildGrid, DogFrame, GRID } from "./dogModel";

// 整体位移（单位：32 网格像素，会被整数化以保持硬边缘）
// x>0 右移、y>0 下沉、y<0 起跳
export interface PaintOffset {
  x?: number;
  y?: number;
  scaleX?: number; // 绕竖轴缩放：转圈时在 1→0→-1 之间摆动，模拟原地转身
  scaleY?: number; // 绕横轴缩放：倒立时取 -1 上下翻转
}

// 将 32x32 颜色网格以整数倍放大绘制到 canvas，关闭平滑保证硬边缘。
// opts.bodyAlpha < 1 时整体淡化，随后把眼睛像素以全不透明二次重绘，突出眼神。
export function paintDog(
  canvas: HTMLCanvasElement,
  frame: DogFrame,
  offset: PaintOffset = {},
  opts: { bodyAlpha?: number } = {}
) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const size = canvas.width; // 正方形
  const cell = size / GRID;
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, size, size);

  const sx = offset.scaleX ?? 1;
  const sy = offset.scaleY ?? 1;
  const transformed = sx !== 1 || sy !== 1;
  if (transformed) {
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.scale(sx, sy);
    ctx.translate(-size / 2, -size / 2);
  }

  const { grid, eyeCells } = buildGrid(frame);
  const bodyAlpha = opts.bodyAlpha ?? 1;
  const ox = Math.round(offset.x ?? 0) * cell; // 左右摇摆
  const oy = Math.round(offset.y ?? 0) * cell; // 呼吸/弹跳
  const paintCell = (x: number, y: number, color: string) => {
    ctx.fillStyle = color;
    ctx.fillRect(
      Math.round(x * cell + ox),
      Math.round(y * cell + oy),
      Math.ceil(cell),
      Math.ceil(cell)
    );
  };

  // 一遍：整体（可淡化）
  ctx.globalAlpha = bodyAlpha;
  for (let y = 0; y < GRID; y++) {
    for (let x = 0; x < GRID; x++) {
      const color = grid[y][x];
      if (!color) continue;
      paintCell(x, y, color);
    }
  }

  // 二遍：眼睛全不透明重绘，令其在淡化的身体上更醒目
  if (bodyAlpha < 1) {
    ctx.globalAlpha = 1;
    for (const [x, y] of eyeCells) {
      const color = grid[y][x];
      if (color) paintCell(x, y, color);
    }
  }

  ctx.globalAlpha = 1;
  if (transformed) ctx.restore();
}

// 生成一张离屏静态头像（用于战绩卡片），返回 dataURL
export function renderDogDataUrl(frame: DogFrame, sizePx = 160): string {
  const c = document.createElement("canvas");
  c.width = sizePx;
  c.height = sizePx;
  paintDog(c, frame);
  return c.toDataURL("image/png");
}
