import { SkinId } from "@/pixel/palette";
import { PetState } from "@/state/types";

export interface SkinInfo {
  id: SkinId;
  name: string;
  desc: string;
}

export const SKIN_INFO: Record<SkinId, SkinInfo> = {
  base: { id: "base", name: "原始形态", desc: "普普通通的奶油棕小狗。" },
  night_owl: {
    id: "night_owl",
    name: "夜猫子",
    desc: "瞳孔变大，自带像素黑眼圈，专治深夜 Debug。",
  },
  workaholic: {
    id: "workaholic",
    name: "卷王",
    desc: "系上像素小领带，眼神坚毅：今天不干完不睡觉。",
  },
  health_guru: {
    id: "health_guru",
    name: "养生达人",
    desc: "戴上像素小浴帽，工位健康委员上线。",
  },
  winter: {
    id: "winter",
    name: "冬至限定",
    desc: "围上像素小围巾，节气到了自动换装。",
  },
};

// 根据行为权重与健康数据，返回本次应解锁的皮肤（可能为空）
export function evaluateUnlocks(pet: PetState): SkinId[] {
  const unlocked = new Set(pet.skins.unlocked);
  const gained: SkinId[] = [];
  const add = (id: SkinId) => {
    if (!unlocked.has(id)) {
      unlocked.add(id);
      gained.push(id);
    }
  };

  // 总在深夜打开 → 夜猫子
  if (pet.counters.lateNightOpens >= 3) add("night_owl");
  // 番茄钟 > 50 次 → 卷王
  if (pet.counters.focusSessions >= 50) add("workaholic");
  // 连续打卡 7 天 → 养生达人
  if (pet.health.streakDays >= 7) add("health_guru");

  return gained;
}

// 傲娇：摸头次数远多于摸下巴
export function isTsundere(pet: PetState): boolean {
  const { petHead, petChin } = pet.counters;
  return petHead >= 8 && petHead > petChin * 2;
}

// 警觉：老板键触发频繁
export function isAlert(pet: PetState): boolean {
  return pet.counters.bossKey >= 5;
}

// 暴躁教练：连续 3 天以上没打卡
export function isGrumpyCoach(pet: PetState): boolean {
  return pet.health.streakDays === 0 && pet.health.totalChecks > 0;
}

// 依据当前状态挑选默认皮肤（已解锁中的优先级）
export function preferredSkin(pet: PetState): SkinId {
  const u = pet.skins.unlocked;
  const now = new Date();
  const isWinter = now.getMonth() === 11; // 12 月近似冬至
  if (isWinter && u.includes("winter")) return "winter";
  if (u.includes("health_guru")) return "health_guru";
  if (u.includes("workaholic")) return "workaholic";
  if (u.includes("night_owl")) return "night_owl";
  return "base";
}
