import { useEffect } from "react";
import { usePetStore } from "@/state/usePetStore";

const TICK_MS = 10_000;

export function useUptimeReminder() {
  const tickReminder = usePetStore((s) => s.tickReminder);

  useEffect(() => {
    const timer = setInterval(tickReminder, TICK_MS);
    tickReminder();
    return () => clearInterval(timer);
  }, [tickReminder]);
}
