import { useEffect, useState } from "react";

interface Props {
  text: string;
  align: "left" | "right";
  vertical: "above" | "below";
}

// 无对话框：小狗上/下方直接显示纯文字。深棕字 + 浅色像素描边光晕（text-halo），
// 透明桌面下也清晰可读；去掉边框盒子后不会再把多行文字挤出窗口顶部。
export default function SpeechBubble({ text, align, vertical }: Props) {
  const [shown, setShown] = useState("");
  const typing = shown.length < text.length;

  useEffect(() => {
    setShown("");
    let i = 0;
    // 放慢打字机速度，文字逐字出现更从容、看得清
    const timer = setInterval(() => {
      i += 1;
      setShown(text.slice(0, i));
      if (i >= text.length) clearInterval(timer);
    }, 60);
    return () => clearInterval(timer);
  }, [text]);

  const posStyle: React.CSSProperties =
    vertical === "below" ? { top: "100%", marginTop: 8 } : { bottom: "100%", marginBottom: 8 };
  if (align === "right") posStyle.right = 2;
  else posStyle.left = 2;

  return (
    <div
      className={`pointer-events-none absolute animate-pop-in z-50 w-[244px] max-w-[92vw] ${
        align === "right" ? "text-right" : "text-left"
      }`}
      style={posStyle}
    >
      <p
        className="text-ink font-body text-[16px] leading-relaxed whitespace-pre-line text-halo"
        style={{ letterSpacing: "2px" }}
      >
        {shown}
        {typing && <span className="animate-blink-caret">▍</span>}
      </p>
    </div>
  );
}
