import { useState } from "react";
import { usePetStore } from "@/state/usePetStore";
import { Gender } from "@/state/types";

const CURRENT_YEAR = new Date().getFullYear();
const YEARS = Array.from({ length: 31 }, (_, i) => CURRENT_YEAR - i);
const MONTHS = Array.from({ length: 12 }, (_, i) => i + 1);

function daysInMonth(year: number, month: number): number {
  return new Date(year, month, 0).getDate();
}

// 首次打开引导：起名 + 性别 + 生日（含年份）
export default function OnboardingModal() {
  const show = usePetStore((s) => s.showOnboarding);
  const complete = usePetStore((s) => s.completeOnboarding);
  const [name, setName] = useState("");
  const [gender, setGender] = useState<Gender>("boy");
  const [year, setYear] = useState(CURRENT_YEAR);
  const [month, setMonth] = useState(1);
  const [day, setDay] = useState(1);

  if (!show) return null;

  const maxDay = daysInMonth(year, month);
  const days = Array.from({ length: maxDay }, (_, i) => i + 1);
  const safeDay = Math.min(day, maxDay);

  const submit = () => {
    const iso = `${year}-${String(month).padStart(2, "0")}-${String(
      safeDay
    ).padStart(2, "0")}`;
    complete(name, gender, iso);
  };

  const genderBtn = (value: Gender) =>
    `flex-1 py-2 font-body border-[3px] border-ink shadow-pixel-sm transition-transform active:translate-x-[2px] active:translate-y-[2px] ${
      gender === value
        ? "bg-grass text-white"
        : "bg-white text-ink hover:bg-paper-dark"
    }`;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-ink/30 backdrop-blur-[1px]" data-interactive>
      <div className="bg-paper pixel-border w-[360px] max-w-[90vw] p-6 animate-pop-in">
        <h2 className="font-display text-2xl text-ink mb-1">你好呀，铲屎官！</h2>
        <p className="font-body text-ink/80 text-sm mb-5">
          这里不错！给我起个名字，选好性别，再告诉我生日吧～
        </p>

        <label className="block font-body text-ink text-sm mb-1">给我起个名字</label>
        <input
          autoFocus
          value={name}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && submit()}
          placeholder="比如：奶狗、旺财、Debug"
          maxLength={12}
          className="w-full bg-white border-[3px] border-ink px-3 py-2 font-body text-ink outline-none mb-4 shadow-pixel-sm"
        />

        <label className="block font-body text-ink text-sm mb-1">我是</label>
        <div className="flex gap-2 mb-4">
          <button type="button" onClick={() => setGender("boy")} className={genderBtn("boy")}>
            弟弟
          </button>
          <button type="button" onClick={() => setGender("girl")} className={genderBtn("girl")}>
            妹妹
          </button>
        </div>

        <label className="block font-body text-ink text-sm mb-1">我的生日</label>
        <div className="flex gap-2 mb-6">
          <select
            value={year}
            onChange={(e) => setYear(Number(e.target.value))}
            className="flex-1 bg-white border-[3px] border-ink px-2 py-2 font-body text-ink outline-none shadow-pixel-sm"
          >
            {YEARS.map((y) => (
              <option key={y} value={y}>{y} 年</option>
            ))}
          </select>
          <select
            value={month}
            onChange={(e) => setMonth(Number(e.target.value))}
            className="flex-1 bg-white border-[3px] border-ink px-2 py-2 font-body text-ink outline-none shadow-pixel-sm"
          >
            {MONTHS.map((m) => (
              <option key={m} value={m}>{m} 月</option>
            ))}
          </select>
          <select
            value={safeDay}
            onChange={(e) => setDay(Number(e.target.value))}
            className="flex-1 bg-white border-[3px] border-ink px-2 py-2 font-body text-ink outline-none shadow-pixel-sm"
          >
            {days.map((d) => (
              <option key={d} value={d}>{d} 日</option>
            ))}
          </select>
        </div>

        <button
          onClick={submit}
          className="w-full bg-grass hover:bg-grass-dark text-white font-display text-xl py-2 border-[3px] border-ink shadow-pixel active:translate-x-[2px] active:translate-y-[2px] active:shadow-pixel-sm transition-transform"
        >
          就这么定啦！
        </button>
      </div>
    </div>
  );
}
