import { C, PaletteColor, SkinId } from "./palette";

export const GRID = 32;

export type EyeStyle =
  | "open"
  | "blink"
  | "happy" // 眯眼享受 ^ ^
  | "closed" // 睡觉 ——
  | "wide" // 兴奋 / 夜猫子大瞳孔
  | "roll" // 翻白眼
  | "sad"; // 幽怨

export type MouthStyle =
  | "smile"
  | "neutral"
  | "open" // 张嘴（焦急/兴奋）
  | "tongue" // 吐舌头（呆萌）
  | "flat"
  | "grin"; // 坚毅

// 姿态：站立 / 奔跑 / 回头 / 趴下 / 坐 / 伸懒腰 / 挠耳 / 嗅地 / 睡觉
export type Pose =
  | "stand"
  | "run"
  | "lookback"
  | "liedown"
  | "sit"
  | "stretch"
  | "scratch"
  | "sniff"
  | "sleep"
  | "battle" // 备战：蓄力前倾
  | "alert"; // 警惕：转向屏幕外侧

export interface DogFrame {
  eye: EyeStyle;
  mouth: MouthStyle;
  legKick: number; // 0..1 迈腿相位
  earTilt: number; // -1..1 耳朵：>0 支棱竖起，<0 耷拉
  look: number; // -1..1 视线水平（跟随光标）
  lookY?: number; // -1..1 视线垂直（跟随光标）
  tailWag: number; // -1..1 摇尾
  blush: boolean;
  skin: SkinId;
  pose?: Pose; // 默认 stand
  headTilt?: number; // -1..1 歪头：整颗头连同耳朵/脸左右偏
}

export type Grid = PaletteColor[][];

type Span = [y: number, x0: number, x1: number];

function emptyGrid(): Grid {
  return Array.from({ length: GRID }, () => Array<PaletteColor>(GRID).fill(null));
}

function clamp(n: number, lo = -1, hi = 1) {
  return Math.max(lo, Math.min(hi, n));
}

// 记录“眼睛”像素坐标（眼白/瞳孔/高光/表情线），供渲染时在淡化的身体之上二次清晰重绘，
// 从而“淡化总体、突出眼神”。每次 buildGrid 开头重置。
let eyeAccum: [number, number][] = [];
function markEye(x: number, y: number) {
  if (x >= 0 && x < GRID && y >= 0 && y < GRID) eyeAccum.push([x, y]);
}

function fillSpans(grid: Grid, spans: Span[], color: PaletteColor, dy = 0, dx = 0) {
  for (const [y, x0, x1] of spans) {
    const yy = y + dy;
    if (yy < 0 || yy >= GRID) continue;
    for (let x = x0 + dx; x <= x1 + dx; x++) {
      if (x < 0 || x >= GRID) continue;
      grid[yy][x] = color;
    }
  }
}

function px(grid: Grid, x: number, y: number, color: PaletteColor) {
  if (x < 0 || x >= GRID || y < 0 || y >= GRID) return;
  grid[y][x] = color;
}

// —— 表情：眼睛 ——（ox,oy 为 6×6 眼眶左上角；眼睛放大成“大眼球”以突出眼神，
// 瞳孔在眼白内随光标 lookX/lookY 平移，读作“眼神跟着鼠标转”）
function drawEye(grid: Grid, ox: number, oy: number, style: EyeStyle, lookX: number, lookY: number) {
  const lx = clamp(lookX);
  const ly = clamp(lookY);
  const set = (x: number, y: number, c: PaletteColor) => {
    if (x < 0 || x >= GRID || y < 0 || y >= GRID) return;
    grid[y][x] = c;
    if (c) markEye(x, y);
  };
  const line = (y: number, x0: number, x1: number, c: PaletteColor) => {
    for (let x = x0; x <= x1; x++) set(x, y, c);
  };

  // 圆润的眼眶（深色描边圈）+ 大片眼白
  const drawBall = () => {
    line(oy, ox + 1, ox + 4, C.outline);
    line(oy + 1, ox, ox + 5, C.outline);
    line(oy + 2, ox, ox + 5, C.outline);
    line(oy + 3, ox, ox + 5, C.outline);
    line(oy + 4, ox, ox + 5, C.outline);
    line(oy + 5, ox + 1, ox + 4, C.outline);
    for (let y = oy + 1; y <= oy + 4; y++) line(y, ox + 1, ox + 4, C.eyeShine);
  };

  // 瞳孔（2×2）在 4×4 眼白内随光标平移，带高光；dilate=兴奋放大
  const drawPupil = (dilate = false) => {
    let cx = ox + 2;
    let cy = oy + 2;
    if (lx > 0.33) cx = ox + 3; else if (lx < -0.33) cx = ox + 1;
    if (ly > 0.33) cy = oy + 3; else if (ly < -0.33) cy = oy + 1;
    cx = Math.max(ox + 1, Math.min(ox + 3, cx));
    cy = Math.max(oy + 1, Math.min(oy + 3, cy));
    line(cy, cx, cx + 1, C.eye);
    line(cy + 1, cx, cx + 1, C.eye);
    if (dilate) {
      line(cy - 1, cx, cx + 1, C.eye);
      line(cy + 2, cx, cx + 1, C.eye);
    }
    set(cx, cy, C.eyeShine); // 高光
  };

  switch (style) {
    case "open":
      drawBall();
      drawPupil(false);
      break;
    case "wide": // 兴奋/夜猫子：瞳孔放大
      drawBall();
      drawPupil(true);
      break;
    case "roll": // 翻白眼：瞳孔顶到最上，露大片眼白
      drawBall();
      line(oy + 1, ox + 2, ox + 3, C.eye);
      line(oy + 2, ox + 2, ox + 3, C.eye);
      set(ox + 2, oy + 1, C.eyeShine);
      break;
    case "sad": // 幽怨：上眼睑压低 + 瞳孔下垂
      drawBall();
      line(oy + 1, ox + 1, ox + 4, C.outline);
      line(oy + 3, ox + 2, ox + 3, C.eye);
      line(oy + 4, ox + 2, ox + 3, C.eye);
      set(ox + 2, oy + 3, C.eyeShine);
      break;
    case "blink": // 眨眼：一条下弯睫毛线
      line(oy + 3, ox + 1, ox + 4, C.outline);
      set(ox, oy + 2, C.outline);
      set(ox + 5, oy + 2, C.outline);
      break;
    case "happy": // ^ ^ 眯眼上弯
      set(ox, oy + 3, C.outline);
      set(ox + 1, oy + 3, C.outline);
      set(ox + 2, oy + 2, C.outline);
      set(ox + 3, oy + 2, C.outline);
      set(ox + 4, oy + 3, C.outline);
      set(ox + 5, oy + 3, C.outline);
      break;
    case "closed": // 睡觉：平静闭眼线，两端微翘
      line(oy + 3, ox, ox + 5, C.outline);
      set(ox, oy + 2, C.outline);
      set(ox + 5, oy + 2, C.outline);
      break;
  }
}

// —— 表情：嘴巴 ——（cx 为中心左列，top 为顶行）
function drawMouth(grid: Grid, cx: number, top: number, style: MouthStyle) {
  switch (style) {
    case "smile":
      px(grid, cx - 1, top, C.outline);
      px(grid, cx, top + 1, C.outline);
      px(grid, cx + 1, top + 1, C.outline);
      px(grid, cx + 2, top, C.outline);
      break;
    case "grin":
      fillSpans(grid, [[top, cx - 2, cx + 3]], C.outline);
      px(grid, cx - 2, top - 1, C.outline);
      px(grid, cx + 3, top - 1, C.outline);
      break;
    case "open":
      fillSpans(grid, [[top, cx - 1, cx + 2], [top + 1, cx - 1, cx + 2]], C.outline);
      fillSpans(grid, [[top + 1, cx, cx + 1]], C.tongue);
      break;
    case "tongue":
      px(grid, cx, top, C.outline);
      px(grid, cx + 1, top, C.outline);
      fillSpans(grid, [[top + 1, cx, cx + 1], [top + 2, cx, cx + 1]], C.tongue);
      px(grid, cx, top + 2, C.noseDark);
      break;
    case "flat":
      fillSpans(grid, [[top, cx - 1, cx + 2]], C.outline);
      break;
    case "neutral":
      px(grid, cx, top, C.outline);
      px(grid, cx + 1, top, C.outline);
      break;
  }
}

// 外描边：任意空像素若正交相邻有实体像素，则填描边色
function applyOutline(grid: Grid) {
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const toOutline: [number, number][] = [];
  for (let y = 0; y < GRID; y++) {
    for (let x = 0; x < GRID; x++) {
      if (grid[y][x] !== null) continue;
      for (const [dx, dy] of dirs) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || nx >= GRID || ny < 0 || ny >= GRID) continue;
        const n = grid[ny][nx];
        if (n !== null && n !== C.outline) {
          toOutline.push([x, y]);
          break;
        }
      }
    }
  }
  for (const [x, y] of toOutline) grid[y][x] = C.outline;
}

// —————————————————————————————————————
// 3/4 微侧朝前柯基（照真实柯基比例）：大头、双三角耳、脸中缝白 blaze、
// 圆身白胸、短腿白爪、身后圆球尾。坐标见 32×32 网格（x 左→右，y 上→下）。
// —————————————————————————————————————

// 大圆头（占上半身，头身比偏大更萌）。y3-4 在两耳之间补出圆顶，避免耳根被描边连成黑横杠
const HEAD: Span[] = [
  [3, 12, 19], [4, 10, 21], [5, 10, 21], [6, 8, 23], [7, 7, 24], [8, 7, 24], [9, 6, 25],
  [10, 6, 25], [11, 6, 25], [12, 6, 25], [13, 7, 24], [14, 7, 24], [15, 8, 23], [16, 10, 21], [17, 12, 19],
];

// 双三角耳（头顶两角，尖朝上略外撇；不细长=不像兔，不外飘大三角=不像驴）
const EAR_L: Span[] = [[0, 7, 8], [1, 6, 9], [2, 6, 10], [3, 6, 11], [4, 6, 12]];
const EAR_R: Span[] = [[0, 23, 24], [1, 22, 25], [2, 21, 25], [3, 20, 25], [4, 19, 25]];
// 粉色内耳（填满耳腔大部，朝内侧偏，呼应参考图明显的浅色内耳）
const EAR_L_IN: Span[] = [[1, 7, 8], [2, 7, 9], [3, 8, 10]];
const EAR_R_IN: Span[] = [[1, 23, 24], [2, 22, 24], [3, 21, 23]];

// 脸中缝白 blaze（柯基招牌）+ 下方白口鼻，一路连到白胸
const BLAZE: Span[] = [
  [8, 14, 17], [9, 14, 17], [10, 13, 18], [11, 13, 18], [12, 12, 19],
  [13, 12, 19], [14, 11, 20], [15, 11, 20], [16, 12, 19], [17, 13, 18],
];

// 紧凑圆身（不拉长，避免像腊肠/驴）
const BODY: Span[] = [
  [17, 9, 22], [18, 8, 23], [19, 7, 24], [20, 6, 24], [21, 6, 24], [22, 6, 24], [23, 7, 23], [24, 9, 22],
];
// 身体中央大片白胸腹
const CHEST: Span[] = [
  [18, 13, 18], [19, 12, 19], [20, 11, 20], [21, 11, 20], [22, 11, 20], [23, 13, 18],
];

// 身后圆球尾（左侧翘起的毛球）
const TAIL: Span[] = [[15, 3, 5], [16, 2, 6], [17, 1, 6], [18, 1, 6], [19, 2, 6], [20, 3, 5]];

// 四条短腿（外侧=后腿略靠后，内侧=前腿）。柯基短腿，收在 y24..27
const LEG_OL: Span[] = [[24, 6, 8], [25, 6, 8], [26, 6, 8]];
const LEG_IL: Span[] = [[24, 10, 12], [25, 10, 12], [26, 10, 12], [27, 10, 12]];
const LEG_IR: Span[] = [[24, 19, 21], [25, 19, 21], [26, 19, 21], [27, 19, 21]];
const LEG_OR: Span[] = [[24, 23, 25], [25, 23, 25], [26, 23, 25]];

function drawCorgiFace(grid: Grid, frame: DogFrame, dx = 0, dy = 0) {
  const lx = clamp(frame.look);
  const ly = clamp(frame.lookY ?? 0);
  drawEye(grid, 8 + dx, 7 + dy, frame.eye, lx, ly); // 左眼（6×6 眼眶）
  drawEye(grid, 18 + dx, 7 + dy, frame.eye, lx, ly); // 右眼
  // 黑鼻头（口鼻中央，上宽下窄的圆润三角）+ 高光
  fillSpans(grid, [[13, 14, 17], [14, 15, 16]], C.eye, dy, dx);
  px(grid, 15 + dx, 13 + dy, C.eyeShine);
  drawMouth(grid, 14 + dx, 15 + dy, frame.mouth);
  if (frame.blush) {
    fillSpans(grid, [[14, 8, 9], [15, 8, 9]], C.blush, dy, dx); // 左颊（眼下）
    fillSpans(grid, [[14, 22, 23], [15, 22, 23]], C.blush, dy, dx); // 右颊
  }
}

// 头部总成（大头 + 双耳 + 粉内耳 + 白 blaze + 脸），整体可 (dx,dy) 偏移，
// 便于歪头（dx）与低头嗅地/趴伸（dy）复用同一张脸
function drawHead(grid: Grid, frame: DogFrame, dx = 0, dy = 0) {
  const earDy = Math.round(-clamp(frame.earTilt) * 2); // 竖起→上移
  fillSpans(grid, HEAD, C.fur, dy, dx);
  fillSpans(grid, EAR_L, C.fur, dy + earDy, dx);
  fillSpans(grid, EAR_R, C.fur, dy + earDy, dx);
  fillSpans(grid, EAR_L_IN, C.blush, dy + earDy, dx);
  fillSpans(grid, EAR_R_IN, C.blush, dy + earDy, dx);
  fillSpans(grid, BLAZE, C.belly, dy, dx);
  drawCorgiFace(grid, frame, dx, dy);
}

// —— 配饰 ——（贴合正面新造型的位置）
function drawCorgiAccessories(grid: Grid, skin: SkinId) {
  if (skin === "night_owl") {
    fillSpans(grid, [[12, 9, 10], [12, 21, 22]], C.darkCircle); // 黑眼圈
  }
  if (skin === "workaholic") {
    fillSpans(grid, [[18, 15, 16]], C.tieDark); // 领带结
    fillSpans(grid, [[19, 15, 16], [20, 15, 16], [21, 15, 16]], C.tie);
  }
  if (skin === "winter") {
    fillSpans(grid, [[17, 9, 22], [18, 10, 21]], C.scarf); // 围巾
    fillSpans(grid, [[19, 12, 14]], C.scarfDark);
  }
  if (skin === "health_guru") {
    fillSpans(grid, [[4, 10, 21], [5, 9, 22]], C.capLight); // 头巾
    fillSpans(grid, [[6, 9, 22]], C.capBand);
  }
}

function buildCorgi(grid: Grid, frame: DogFrame, run: boolean) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const headDx = Math.round(clamp(frame.headTilt ?? 0)); // 歪头 ±1px
  const p = frame.legKick > 0.5;

  // 身后圆球尾（先画，摇摆左右）
  fillSpans(grid, TAIL, C.fur, 0, wag);

  // 外侧后腿（深色增加层次），奔跑时前后错开
  fillSpans(grid, LEG_OL, C.furDark, 0, run ? (p ? 1 : -1) : 0);
  fillSpans(grid, LEG_OR, C.furDark, 0, run ? (p ? -1 : 1) : 0);

  // 身体 + 白胸腹
  fillSpans(grid, BODY, C.fur);
  fillSpans(grid, CHEST, C.belly);

  // 内侧前腿（浅色），奔跑时上下交替迈步
  const kickL = run ? (p ? -1 : 0) : 0;
  const kickR = run ? (p ? 0 : -1) : 0;
  fillSpans(grid, LEG_IL, C.fur, kickL);
  fillSpans(grid, LEG_IR, C.fur, kickR);

  // 白爪（收到腿底，柯基短腿）
  fillSpans(grid, [[26, 6, 8], [26, 23, 25]], C.belly); // 后爪
  fillSpans(grid, [[27, 10, 12]], C.belly, kickL); // 前爪（左）
  fillSpans(grid, [[27, 19, 21]], C.belly, kickR); // 前爪（右）

  // 头部总成（含歪头偏移）+ 配饰
  drawHead(grid, frame, headDx, 0);
  drawCorgiAccessories(grid, frame.skin);

  // 奔跑：两侧速度线
  if (run) {
    px(grid, 1, 12, C.furShade); px(grid, 0, 14, C.furShade); px(grid, 1, 16, C.furShade);
    px(grid, 30, 12, C.furShade); px(grid, 31, 14, C.furShade); px(grid, 30, 16, C.furShade);
  }
}

// —————————————————————————————————————
// 趴下（正面 sphinx 趴姿）：身体压低摊平、前腿向前平伸、抬头看你
// —————————————————————————————————————
function buildCorgiLie(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const D = 3; // 头/脸相对站立整体下移，头压低呈趴姿

  // 身后圆球尾（左侧，压低）
  fillSpans(grid, [[20, 2, 5], [21, 1, 6], [22, 1, 6], [23, 2, 5]], C.fur, 0, wag);

  // 摊平加宽的身体（贴地的低矮圆饼）
  fillSpans(grid, [
    [22, 8, 23], [23, 5, 26], [24, 4, 27], [25, 4, 27], [26, 5, 26], [27, 7, 24],
  ], C.fur);
  // 白胸腹（中央）
  fillSpans(grid, [[24, 12, 19], [25, 12, 19], [26, 13, 18]], C.belly);

  // 向前平伸的两条前腿 + 白爪（趴姿招牌）
  fillSpans(grid, [[27, 9, 12], [28, 9, 12], [29, 9, 12]], C.fur); // 左前腿
  fillSpans(grid, [[27, 19, 22], [28, 19, 22], [29, 19, 22]], C.fur); // 右前腿
  fillSpans(grid, [[29, 8, 12]], C.belly); // 左前爪
  fillSpans(grid, [[29, 19, 23]], C.belly); // 右前爪

  // 抬起的头 —— 复用站立头型，整体下移 D
  drawHead(grid, frame, 0, D);
}

// —————————————————————————————————————
// 坐姿：臀部落地、身体上窄下宽后坐，两条前腿在身前撑直，头保持正常高度
// —————————————————————————————————————
const SIT_BODY: Span[] = [
  [16, 11, 20], [17, 10, 21], [18, 9, 22], [19, 8, 23],
  [20, 7, 24], [21, 6, 25], [22, 6, 25], [23, 6, 25],
];
const SIT_CHEST: Span[] = [
  [17, 13, 18], [18, 12, 19], [19, 12, 19], [20, 12, 19], [21, 13, 18],
];
const SIT_TAIL: Span[] = [[18, 3, 5], [19, 2, 6], [20, 1, 6], [21, 2, 6], [22, 3, 5]];

function buildCorgiSit(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const headDx = Math.round(clamp(frame.headTilt ?? 0));

  // 贴在身侧靠下的尾巴
  fillSpans(grid, SIT_TAIL, C.fur, 0, wag);
  // 后坐的身体 + 白胸腹
  fillSpans(grid, SIT_BODY, C.fur);
  fillSpans(grid, SIT_CHEST, C.belly);
  // 折叠的后爪从两侧探出
  fillSpans(grid, [[23, 6, 8], [23, 23, 25]], C.belly);
  // 两条前腿竖立在身前 + 白爪
  fillSpans(grid, [[21, 11, 13], [22, 11, 13], [23, 11, 13]], C.fur);
  fillSpans(grid, [[21, 18, 20], [22, 18, 20], [23, 18, 20]], C.fur);
  fillSpans(grid, [[24, 11, 13]], C.belly);
  fillSpans(grid, [[24, 18, 20]], C.belly);

  drawHead(grid, frame, headDx, 0);
  drawCorgiAccessories(grid, frame.skin);
}

// —————————————————————————————————————
// 抬后腿挠耳：坐姿身体，右后腿竖起贴脸抓挠（legKick 驱动上下抖动），头朝那侧歪
// —————————————————————————————————————
function buildCorgiScratch(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const scratch = frame.legKick > 0.5 ? -1 : 0; // 抓挠上下抖动

  fillSpans(grid, SIT_TAIL, C.fur, 0, wag);
  fillSpans(grid, SIT_BODY, C.fur);
  fillSpans(grid, SIT_CHEST, C.belly);
  // 左侧折叠后爪 + 撑地的左前腿
  fillSpans(grid, [[23, 6, 8]], C.belly);
  fillSpans(grid, [[21, 11, 13], [22, 11, 13], [23, 11, 13]], C.fur);
  fillSpans(grid, [[24, 11, 13]], C.belly);

  // 头朝挠痒侧（右）微歪
  drawHead(grid, frame, 1, 0);

  // 抬起的右后腿：竖直贴右侧上抬到耳朵下，抓挠时随 scratch 抖动
  fillSpans(grid, [
    [21, 25, 27], [20, 25, 27], [19, 25, 27], [18, 25, 27],
    [17, 25, 27], [16, 25, 27], [15, 25, 27], [14, 25, 27],
  ], C.furDark, scratch);
  fillSpans(grid, [[13, 25, 27]], C.belly, scratch); // 挠痒的后爪（贴近右耳/脸颊）
}

// —————————————————————————————————————
// 低头嗅地：复用站立身体与四腿，头整体下探贴近地面，耳朵前耷
// —————————————————————————————————————
function buildCorgiSniff(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const D = 8; // 头下探

  fillSpans(grid, TAIL, C.fur, 0, wag);
  fillSpans(grid, LEG_OL, C.furDark);
  fillSpans(grid, LEG_OR, C.furDark);
  fillSpans(grid, BODY, C.fur);
  fillSpans(grid, CHEST, C.belly);
  fillSpans(grid, LEG_IL, C.fur);
  fillSpans(grid, LEG_IR, C.fur);
  fillSpans(grid, [[26, 6, 8], [26, 23, 25]], C.belly); // 后爪
  fillSpans(grid, [[27, 10, 12], [27, 19, 21]], C.belly); // 前爪

  // 低下的头
  drawHead(grid, frame, 0, D);

  // 鼻子前下方的小气味点（嗅探暗示）
  px(grid, 12, 25, C.furShade);
  px(grid, 19, 26, C.furShade);
}

// —————————————————————————————————————
// 伸懒腰打哈欠（play bow）：后半身与尾巴高高翘起、前身压低、前腿向前平伸，配张嘴哈欠
// —————————————————————————————————————
function buildCorgiStretch(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);
  const D = 6; // 头前伸压低

  // 高高翘起的尾巴（后半身抬高）
  fillSpans(grid, [[9, 3, 5], [10, 2, 6], [11, 1, 6], [12, 2, 6], [13, 3, 6]], C.fur, 0, wag);

  // 后高前低的“作揖/趴伸”身体
  fillSpans(grid, [
    [13, 7, 12], [14, 6, 16], [15, 6, 19], [16, 6, 22],
    [17, 7, 23], [18, 8, 23], [19, 10, 23], [20, 12, 22],
  ], C.fur);
  // 白胸腹（前下方贴地）
  fillSpans(grid, [[19, 13, 20], [20, 14, 20], [21, 14, 20]], C.belly);

  // 向前平伸贴地的前腿 + 白爪
  fillSpans(grid, [[22, 13, 15], [23, 12, 15], [24, 11, 15]], C.fur);
  fillSpans(grid, [[22, 18, 20], [23, 18, 21], [24, 18, 22]], C.fur);
  fillSpans(grid, [[25, 10, 15]], C.belly);
  fillSpans(grid, [[25, 18, 23]], C.belly);

  // 低下前伸的头（打哈欠表情由 animator 提供：闭眼 + 张大嘴）
  drawHead(grid, frame, 0, D);
}

// —————————————————————————————————————
// 睡觉：蜷成一团贴地小憩，前腿收在身前、头低垂枕在爪上，闭眼（表情由 animator 给）
// —————————————————————————————————————
function buildCorgiSleep(grid: Grid, frame: DogFrame) {
  const D = 6; // 头低垂枕地

  // 蜷到身侧的尾巴（收拢盖在屁股上）
  fillSpans(grid, [[20, 3, 6], [21, 2, 6], [22, 2, 6], [23, 3, 6]], C.fur);

  // 团成一团的圆背（比趴姿更高更圆，像缩着睡）
  fillSpans(grid, [
    [20, 10, 22], [21, 8, 24], [22, 6, 25], [23, 5, 26],
    [24, 4, 27], [25, 4, 27], [26, 5, 26], [27, 7, 24],
  ], C.fur);
  // 白胸腹
  fillSpans(grid, [[24, 12, 19], [25, 12, 19], [26, 13, 18]], C.belly);

  // 蜷收在身前的前腿 + 白爪（不外伸，枕着睡）
  fillSpans(grid, [[27, 10, 13], [28, 10, 13]], C.fur);
  fillSpans(grid, [[27, 18, 21], [28, 18, 21]], C.fur);
  fillSpans(grid, [[28, 9, 13]], C.belly);
  fillSpans(grid, [[28, 18, 22]], C.belly);

  // 低垂入睡的头（复用站立头型下沉，闭眼由 animator 提供）
  drawHead(grid, frame, 0, D);
}

// —————————————————————————————————————
// 备战：后腿蹬地、身体前倾压低蓄力、头前探（瞪眼竖耳由 animator 提供），预备扑出
// —————————————————————————————————————
function buildCorgiBattle(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);

  // 绷直上扬的战斗尾（后方斜上，警戒）
  fillSpans(grid, [[11, 3, 5], [12, 2, 6], [13, 2, 6], [14, 3, 6]], C.fur, 0, wag);

  // 抬高的后半身 + 向前下斜的脊背
  fillSpans(grid, [
    [15, 16, 23], [16, 13, 24], [17, 11, 24], [18, 10, 23], [19, 10, 22],
  ], C.fur);
  // 压低前伸的前胸/肩
  fillSpans(grid, [[20, 10, 21], [21, 11, 21]], C.fur);
  // 白胸腹（蓄力前压）
  fillSpans(grid, [[18, 14, 19], [19, 13, 19], [20, 13, 18]], C.belly);

  // 后腿蹬地（右后，深色，略抬）
  fillSpans(grid, [[19, 22, 24], [20, 22, 24], [21, 22, 24]], C.furDark);
  fillSpans(grid, [[22, 22, 24]], C.belly);

  // 前腿撑地微屈（左前，压低）
  fillSpans(grid, [[21, 10, 12], [22, 10, 12]], C.fur);
  fillSpans(grid, [[21, 16, 18], [22, 16, 18]], C.fur);
  fillSpans(grid, [[23, 10, 12]], C.belly);
  fillSpans(grid, [[23, 16, 18]], C.belly);

  // 前探压低的头
  drawHead(grid, frame, 0, 3);
}

// —————————————————————————————————————
// 警惕：站立转向屏幕外侧（右），头扭向外、竖耳盯梢（表情/竖耳由 animator 提供）
// —————————————————————————————————————
function buildCorgiAlert(grid: Grid, frame: DogFrame) {
  const wag = Math.round(clamp(frame.tailWag) * 2);

  // 站立身体（复用站立造型的躯干与四腿）
  fillSpans(grid, TAIL, C.fur, 0, wag);
  fillSpans(grid, LEG_OL, C.furDark);
  fillSpans(grid, LEG_OR, C.furDark);
  fillSpans(grid, BODY, C.fur);
  fillSpans(grid, CHEST, C.belly);
  fillSpans(grid, LEG_IL, C.fur);
  fillSpans(grid, LEG_IR, C.fur);
  fillSpans(grid, [[26, 6, 8], [26, 23, 25]], C.belly); // 后爪
  fillSpans(grid, [[27, 10, 12], [27, 19, 21]], C.belly); // 前爪

  // 头整体扭向屏幕外侧（右）并略压低，为竖起的耳朵留出顶部空间 + 配饰
  drawHead(grid, frame, 3, 2);
  drawCorgiAccessories(grid, frame.skin);
}

// 全局下移量：为起跳/呼吸上浮预留顶部空间，避免耳朵被画布上边裁掉
const VSHIFT = 2;
// 将整幅网格下移 dy 行（顶部补空、底部溢出丢弃），保持硬边缘
function shiftDown(grid: Grid, dy: number) {
  if (dy <= 0) return;
  for (let y = GRID - 1; y >= 0; y--) {
    const src = y - dy;
    grid[y] = src >= 0 ? grid[src] : Array<PaletteColor>(GRID).fill(null);
  }
}

export function buildGrid(frame: DogFrame): { grid: Grid; eyeCells: [number, number][] } {
  eyeAccum = [];
  const g = emptyGrid();
  const pose = frame.pose ?? "stand";
  switch (pose) {
    case "run":
      buildCorgi(g, frame, true);
      break;
    case "liedown":
      buildCorgiLie(g, frame);
      break;
    case "sit":
      buildCorgiSit(g, frame);
      break;
    case "scratch":
      buildCorgiScratch(g, frame);
      break;
    case "sniff":
      buildCorgiSniff(g, frame);
      break;
    case "stretch":
      buildCorgiStretch(g, frame);
      break;
    case "sleep":
      buildCorgiSleep(g, frame);
      break;
    case "battle":
      buildCorgiBattle(g, frame);
      break;
    case "alert":
      buildCorgiAlert(g, frame);
      break;
    case "lookback": // 已是 3/4 侧身，复用站立
    case "stand":
    default:
      buildCorgi(g, frame, false);
      break;
  }
  // 趴/睡姿只轻微下沉不上浮，保持贴地；其余姿态整体下移，留出上浮余量
  const shift = pose !== "liedown" && pose !== "sleep" ? VSHIFT : 0;
  if (shift) shiftDown(g, shift);
  applyOutline(g);
  // 眼睛像素坐标随整体下移对齐，供渲染层清晰重绘
  const eyeCells = eyeAccum.map(([x, y]) => [x, y + shift] as [number, number]);
  return { grid: g, eyeCells };
}
