import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { usePetStore } from "@/state/usePetStore";
import { paintDog } from "@/pixel/renderer";
import { computeFrame } from "@/pixel/animator";
import { DogFrame } from "@/pixel/dogModel";
import { isDesktop, moveWindowBy, getDesktopApi } from "@/utils/desktop";
import SpeechBubble from "./SpeechBubble";

const DISPLAY_FULL = 192;
const DISPLAY_MINI = 96;
const IDLE_PAUSE_MS = 10_000;
const BODY_FADE = 0.85; // 主视觉淡化：身体略透明，眼睛仍全不透明重绘以突出眼神
const LOOK_RANGE = 120; // 视线灵敏度：距中心多少 px 到达最大偏转（越小越灵敏）

export default function DogCanvas() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);

  const pet = usePetStore((s) => s.pet);
  const mood = usePetStore((s) => s.mood);
  const bubble = usePetStore((s) => s.bubble);
  const hidden = usePetStore((s) => s.hidden);
  const petHead = usePetStore((s) => s.petHead);
  const petChin = usePetStore((s) => s.petChin);
  const startFocus = usePetStore((s) => s.startFocus);
  const setPosition = usePetStore((s) => s.setPosition);

  const desktop = isDesktop();
  const DISPLAY = desktop ? DISPLAY_MINI : DISPLAY_FULL;

  const [pos, setPos] = useState<{ x: number; y: number }>(() => {
    // 桌面悬浮窗：小狗贴近底部（工具条上方），上方留足高度给多行气泡，避免文字被窗口顶部裁掉
    if (desktop) {
      return {
        x: Math.max(0, (window.innerWidth - DISPLAY) / 2),
        y: Math.max(12, window.innerHeight - DISPLAY - 48),
      };
    }
    return {
      x: pet.position.x >= 0 ? pet.position.x : Math.max(24, window.innerWidth - DISPLAY - 32),
      y: pet.position.y >= 0 ? pet.position.y : 28,
    };
  });

  // 用 ref 承载高频状态，避免每帧 re-render
  const lookRef = useRef({ x: 0, y: 0 });
  const lastActivity = useRef(Date.now());
  const moodRef = useRef(mood);
  const skinRef = useRef(pet.skins.active);
  const runningRef = useRef(false);
  const tsundereIdleRef = useRef(false);

  moodRef.current = mood;
  skinRef.current = pet.skins.active;
  tsundereIdleRef.current =
    pet.weights.tsundere >= 8 && pet.counters.petHead > pet.counters.petChin * 2;

  // 拖拽
  const drag = useRef({ active: false, moved: false, sx: 0, sy: 0, ox: 0, oy: 0, dist: 0 });
  const clickTimes = useRef<number[]>([]);
  const resolveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastClick = useRef<{ head: boolean }>({ head: true });

  useLayoutEffect(() => {
    const onMove = (e: PointerEvent) => {
      // 光标跟随（眼神/视线）：以画布中心为原点，换算到 -1..1
      const rect = wrapRef.current?.getBoundingClientRect();
      if (rect) {
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        lookRef.current = {
          x: Math.max(-1, Math.min(1, (e.clientX - cx) / LOOK_RANGE)),
          y: Math.max(-1, Math.min(1, (e.clientY - cy) / LOOK_RANGE)),
        };
      }
      lastActivity.current = Date.now();
      if (!runningRef.current) startLoop();
      if (!drag.current.active) return;
      // 桌面模式且注入了移窗能力：拖动改为移动整个悬浮窗（窗口跟随光标，用增量判定）。
      // 若身处 Electron 但没有 preload API（IDE 预览等），退化为 CSS 定位拖动，保证仍能拖动。
      if (desktop && getDesktopApi()) {
        moveWindowBy(e.movementX, e.movementY);
        drag.current.dist += Math.abs(e.movementX) + Math.abs(e.movementY);
        if (drag.current.dist > 4) drag.current.moved = true;
        return;
      }
      const nx = drag.current.ox + (e.clientX - drag.current.sx);
      const ny = drag.current.oy + (e.clientY - drag.current.sy);
      if (Math.abs(e.clientX - drag.current.sx) + Math.abs(e.clientY - drag.current.sy) > 4)
        drag.current.moved = true;
      const clampedX = Math.max(0, Math.min(window.innerWidth - DISPLAY, nx));
      const clampedY = Math.max(0, Math.min(window.innerHeight - DISPLAY, ny));
      setPos({ x: clampedX, y: clampedY });
    };
    const onUp = (e: PointerEvent) => {
      if (!drag.current.active) return;
      drag.current.active = false;
      // 用 CSS 定位拖动（无移窗能力）时才持久化坐标
      if (!getDesktopApi() && drag.current.moved) {
        setPos((p) => {
          setPosition(p.x, p.y);
          return p;
        });
      }
      canvasRef.current?.releasePointerCapture(e.pointerId);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [setPosition]);

  // 渲染循环（闲置/隐藏时暂停以省资源）
  useEffect(() => {
    let raf = 0;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const tick = () => {
      const now = performance.now();
      const idle = Date.now() - lastActivity.current > IDLE_PAUSE_MS;
      const paused = document.hidden || (idle && moodRef.current === "idle");
      const out = computeFrame({
        mood: moodRef.current,
        tMs: now,
        skin: skinRef.current,
        look: lookRef.current.x,
        lookY: lookRef.current.y,
        tsundereIdle: tsundereIdleRef.current,
      });
      paintDog(canvas, out.frame as DogFrame, out.offset, { bodyAlpha: BODY_FADE });
      if (paused) {
        runningRef.current = false;
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    (window as unknown as { __startDogLoop?: () => void }).__startDogLoop = () => {
      if (runningRef.current) return;
      runningRef.current = true;
      raf = requestAnimationFrame(tick);
    };
    runningRef.current = true;
    raf = requestAnimationFrame(tick);

    const onVisible = () => {
      lastActivity.current = Date.now();
      if (!runningRef.current) startLoop();
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      cancelAnimationFrame(raf);
      runningRef.current = false;
      document.removeEventListener("visibilitychange", onVisible);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function startLoop() {
    (window as unknown as { __startDogLoop?: () => void }).__startDogLoop?.();
  }

  // mood 变化时确保循环在跑
  useEffect(() => {
    lastActivity.current = Date.now();
    startLoop();
  }, [mood, pet.skins.active]);

  // 闲置时偶尔自发做点生活化小动作，让待机不再单调
  useEffect(() => {
    const id = setInterval(() => {
      const s = usePetStore.getState();
      if (s.hidden || s.focus || s.reminder || s.showOnboarding) return;
      if (s.mood !== "idle") return;
      const r = Math.random();
      if (r < 0.18) s.setMood("sleep", 22000); // 睡觉：停留更久
      else if (r < 0.32) s.setMood("liedown", 4200);
      else if (r < 0.46) s.setMood("sit", 5000);
      else if (r < 0.56) s.setMood("sniff", 2800);
      else if (r < 0.66) s.setMood("scratch", 2200);
      else if (r < 0.76) s.setMood("stretch", 2000);
      else if (r < 0.85) s.setMood("handstand", 2600); // 倒立
      else if (r < 0.93) s.setMood("spin", 2400); // 转圈
      else s.setMood("run", 2200);
      lastActivity.current = Date.now();
      startLoop();
    }, 11_000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onPointerDown = (e: React.PointerEvent) => {
    const api = getDesktopApi();
    if (api) {
      api.setMouseIgnore(false);
    }
    drag.current = {
      active: true,
      moved: false,
      sx: e.clientX,
      sy: e.clientY,
      ox: pos.x,
      oy: pos.y,
      dist: 0,
    };
    const rect = wrapRef.current?.getBoundingClientRect();
    lastClick.current.head = rect ? e.clientY - rect.top < rect.height * 0.5 : true;
    lastActivity.current = Date.now();
    canvasRef.current?.setPointerCapture(e.pointerId);
  };

  const onClick = () => {
    if (drag.current.moved) return;
    const now = Date.now();
    clickTimes.current = clickTimes.current.filter((t) => now - t < 800);
    clickTimes.current.push(now);
    if (resolveTimer.current) clearTimeout(resolveTimer.current);
    const headHit = lastClick.current.head;
    resolveTimer.current = setTimeout(() => {
      if (clickTimes.current.length >= 3) {
        startFocus();
      } else if (headHit) {
        petHead();
      } else {
        petChin();
      }
      clickTimes.current = [];
    }, 300);
  };

  if (hidden) return null;

  return (
    <div
      ref={wrapRef}
      data-interactive
      className="fixed z-40 no-select"
      style={{ left: pos.x, top: pos.y, width: DISPLAY, height: DISPLAY, touchAction: "none" }}
    >
      {bubble && (
        <SpeechBubble
          key={bubble.id}
          text={bubble.text}
          align={desktop ? "left" : pos.x + DISPLAY / 2 > window.innerWidth / 2 ? "right" : "left"}
          vertical={desktop ? "above" : pos.y < window.innerHeight * 0.45 ? "below" : "above"}
        />
      )}
      <div className="relative animate-pop-in" style={{ width: DISPLAY, height: DISPLAY, animationDuration: "0.4s" }}>
        {mood === "sleep" && (
          <div className="absolute -top-2 right-6 font-pixel text-ink text-sm animate-bob select-none">
            Z<span className="text-xs">z</span>
          </div>
        )}
        <canvas
          ref={canvasRef}
          width={DISPLAY}
          height={DISPLAY}
          onPointerDown={onPointerDown}
          onClick={onClick}
          className="pixelated cursor-grab active:cursor-grabbing"
          style={{ filter: "drop-shadow(3px 4px 0 rgba(74,53,39,0.35))" }}
          title="单击头部摸头 · 单击身体挠痒 · 连点三下开启专注"
        />
      </div>
    </div>
  );
}
