import { DiaryEntry, PetState } from "@/state/types";
import { todayISO } from "@/utils/date";

type Mood = DiaryEntry["mood"];

// 依据当日互动数据推断情绪
function inferMood(pet: PetState): Mood {
  const { petHead, petChin, focusSessions, bossKey } = pet.counters;
  const checks = pet.health.todayTypes.length;
  if (focusSessions > 0 && checks >= 2) return "proud";
  if (petHead + petChin >= 6) return "happy";
  if (bossKey >= 3) return "angry";
  if (checks === 0 && petHead + petChin === 0) return "tired";
  return "calm";
}

const OPENERS: Record<Mood, string[]> = {
  happy: ["今天被摸了好多下，尾巴摇到发烫。", "阳光正好，你的手也正好。"],
  proud: ["主人今天超能打，我在旁边骄傲得胡子都翘起来了。", "专注又养生，这就是我的完美铲屎官。"],
  angry: ["老板键按到我耳朵疼，今天的空气里都是紧张味。", "有人一直在藏我，哼，但我懂，都是为了活下去。"],
  tired: ["今天你太安静了，我趴了一整天，连梦都是灰色的。", "工位好冷清，我把尾巴卷成一团取暖。"],
  calm: ["平平淡淡的一天，我数了数窗外的云。", "没什么大事，能陪着你就很好。"],
};

const CLOSERS: Record<Mood, string> = {
  happy: "明天也要这样，好不好？",
  proud: "明天继续，我给你当护卫。",
  angry: "明天需要我帮你咬碎谁的方案吗？",
  tired: "明天多摸摸我，我会把颜色还给你。",
  calm: "晚安，明天见。",
};

// 本地生成「像素狗日记」（降级方案，不外发数据）
export function generateDiary(pet: PetState): DiaryEntry {
  const mood = inferMood(pet);
  const opener = OPENERS[mood][Math.floor(Math.random() * OPENERS[mood].length)];
  const stats = {
    摸头: pet.counters.petHead,
    摸下巴: pet.counters.petChin,
    专注: pet.counters.focusSessions,
    健康打卡: pet.health.todayTypes.length,
    老板键: pet.counters.bossKey,
  };
  const statLine = `（今日：摸头${stats.摸头}·专注${stats.专注}·打卡${stats.健康打卡}）`;
  const text = `${opener}${statLine}${CLOSERS[mood]}`;
  return { date: todayISO(), text, mood, stats };
}

// 依据昨日日记情绪生成今日开场白
export function greetingFromDiary(diary: DiaryEntry[], name: string): string | null {
  if (diary.length === 0) return null;
  const last = diary[diary.length - 1];
  const n = name || "小狗";
  switch (last.mood) {
    case "angry":
      return `今天需要我帮你咬碎谁的方案吗？（${n}已经磨好牙了）`;
    case "tired":
      return "昨天你有点累，今天先深呼吸，我陪着你。";
    case "proud":
      return "昨天那么能打，今天也别忘了喝水呀！";
    case "happy":
      return "昨天笑得那么开心，今天继续摸我好不好？";
    default:
      return "又是新的一天，早呀！";
  }
}
